module apb_pwm_controller (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        psel,
    input  logic        penable,
    input  logic        pwrite,
    input  logic [9:0]  paddr,
    input  logic [31:0] pwdata,
    output logic [31:0] prdata,
    output logic        pready,
    output logic        pwm_out
);

    // Internal registers
    logic [31:0] ctrl_reg;
    logic [31:0] period_reg;
    logic [31:0] duty_reg;
    logic [31:0] current_count;
    logic        pwm_enabled;

    // Address decode signals
    logic is_ctrl_addr;
    logic is_period_addr;
    logic is_duty_addr;

    assign is_ctrl_addr   = (paddr == 10'h000);
    assign is_period_addr = (paddr == 10'h004);
    assign is_duty_addr   = (paddr == 10'h008);

    // APB FSM
    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        SETUP   = 2'b01,
        ACCESS  = 2'b10,
        WAIT    = 2'b11
    } apb_state_t;

    apb_state_t apb_current_state, apb_next_state;

    // APB Response Logic
    always_comb begin
        case(apb_current_state)
            ACCESS: pready = 1'b1;
            default: pready = 1'b0;
        endcase
    end

    // APB FSM state transition
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            apb_current_state <= IDLE;
        else
            apb_current_state <= apb_next_state;
    end

    // APB FSM next state logic
    always_comb begin
        case(apb_current_state)
            IDLE: begin
                if (psel)
                    apb_next_state = SETUP;
                else
                    apb_next_state = IDLE;
            end
            SETUP: begin
                if (penable)
                    apb_next_state = ACCESS;
                else
                    apb_next_state = SETUP;
            end
            ACCESS: begin
                apb_next_state = IDLE;
            end
            default: apb_next_state = IDLE;
        endcase
    end

    // Register write logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ctrl_reg <= 32'h0;
            period_reg <= 32'd1000;
            duty_reg <= 32'd500;
        end else if (apb_current_state == ACCESS && pwrite) begin
            if (is_ctrl_addr) ctrl_reg <= pwdata;
            if (is_period_addr) period_reg <= pwdata;
            if (is_duty_addr) duty_reg <= pwdata;
        end
    end

    // Register read logic
    always_comb begin
        prdata = 32'h0;
        if (apb_current_state == ACCESS && !pwrite) begin
            if (is_ctrl_addr) prdata = ctrl_reg;
            if (is_period_addr) prdata = period_reg;
            if (is_duty_addr) prdata = duty_reg;
        end
    end

    // PWM Control FSM
    typedef enum logic {
        LOW_STATE  = 1'b0,
        HIGH_STATE = 1'b1
    } pwm_state_t;

    pwm_state_t pwm_current_state, pwm_next_state;

    // Latch enable signal
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm_enabled <= 1'b0;
        else
            pwm_enabled <= ctrl_reg[0];
    end

    // Counter logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_count <= 32'd0;
        end else if (!pwm_enabled) begin
            current_count <= 32'd0;
        end else begin
            if (current_count >= (period_reg - 1))
                current_count <= 32'd0;
            else
                current_count <= current_count + 1;
        end
    end

    // PWM State Machine
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm_current_state <= LOW_STATE;
        else
            pwm_current_state <= pwm_next_state;
    end

    // Next state logic
    always_comb begin
        case(pwm_current_state)
            LOW_STATE: begin
                if (!pwm_enabled)
                    pwm_next_state = LOW_STATE;
                else if (current_count >= (period_reg - duty_reg))
                    pwm_next_state = HIGH_STATE;
                else
                    pwm_next_state = LOW_STATE;
            end

            HIGH_STATE: begin
                if (!pwm_enabled)
                    pwm_next_state = LOW_STATE;
                else if (current_count >= duty_reg)
                    pwm_next_state = LOW_STATE;
                else
                    pwm_next_state = HIGH_STATE;
            end

            default: pwm_next_state = LOW_STATE;
        endcase
    end

    // Output assignment
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pwm_out <= 1'b0;
        else
            pwm_out <= (pwm_enabled) ? pwm_current_state : 1'b0;
    end

endmodule

