    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Test task
    task automatic run_test();
        // Reset sequence
        rst_n = 0;
        repeat(10) @(posedge clk);
        rst_n = 1;
        repeat(10) @(posedge clk);

        // Test 1: Write and read CTRL register
        write_register(10'h000, 32'h1); // Enable PWM
        read_and_check(10'h000, 32'h1);

        // Test 2: Write and read PERIOD register
        write_register(10'h004, 32'd1000);
        read_and_check(10'h004, 32'd1000);

        // Test 3: Write and read DUTY register
        write_register(10'h008, 32'd500);
        read_and_check(10'h008, 32'd500);

        // Test 4: Check PWM output behavior
        check_pwm_output();

        $display("TEST PASSED");
        $finish;
    endtask

    // Task to perform APB write transaction
    task automatic write_register(input [9:0] addr, input [31:0] data);
        @(posedge clk);
        psel    <= 1;
        pwrite  <= 1;
        paddr   <= addr;
        pwdata  <= data;

        @(posedge clk);
        penable <= 1;

        wait(pready == 1);
        @(posedge clk);

        psel    <= 0;
        penable <= 0;
        pwrite  <= 0;
    endtask

    // Task to perform APB read transaction and check data
    task automatic read_and_check(input [9:0] addr, input [31:0] expected_data);
        logic [31:0] read_data;

        @(posedge clk);
        psel    <= 1;
        pwrite  <= 0;
        paddr   <= addr;

        @(posedge clk);
        penable <= 1;

        wait(pready == 1);
        read_data = prdata;
        @(posedge clk);

        psel    <= 0;
        penable <= 0;

        if (read_data !== expected_data) begin
            $display("ERROR: Read data mismatch at address %h. Expected %h, Got %h", addr, expected_data, read_data);
            $finish;
        end
    endtask

    // Task to check PWM output behavior
    task automatic check_pwm_output();
        int count_high, count_low;
        logic prev_pwm;

        // Wait for a few cycles to let PWM stabilize
        repeat(10) @(posedge clk);

        // Measure high time
        count_high = 0;
        prev_pwm = pwm_out;
        while (count_high < 500) begin
            @(posedge clk);
            if (pwm_out == 1) 
                count_high++;
            else if (count_high > 0) 
                break; // Stop when we see a transition to low
        end

        // Measure low time
        count_low = 0;
        while (count_low < 500) begin
            @(posedge clk);
            if (pwm_out == 0) 
                count_low++;
            else if (count_low > 0) 
                break; // Stop when we see a transition to high
        end

        // Basic check - just verify that we see both high and low states
        if (count_high == 0 || count_low == 0) begin
            $display("ERROR: PWM output not toggling correctly");
            $finish;
        end
    endtask

    // Initialize signals
    initial begin
        psel    = 0;
        penable = 0;
        pwrite  = 0;
        paddr   = 0;
        pwdata  = 0;

        run_test();
    end

