module apb_watchdog_timer (
    // Clocking and Reset
    input  logic         pclk,
    input  logic         preset_n,
    input  logic         ext_clk,

    // Watchdog Outputs
    output logic         wdg_rst_n,
    output logic         irq,

    // APB Interface
    input  logic         psel,
    input  logic         penable,
    input  logic [7:0]   paddr,
    input  logic         pwrite,
    input  logic [31:0]  pwdata,
    output logic [31:0]  prdata,
    output logic         pready,
    output logic         pslverr
);

    // Register addresses
    localparam ADDR_RELOAD_VAL  = 8'h00;
    localparam ADDR_CURRENT_VAL = 8'h04;
    localparam ADDR_CTRL        = 8'h08;
    localparam ADDR_RESERVED    = 8'h0C;

    // APB FSM States
    typedef enum logic [1:0] {
        IDLE     = 2'b00,
        SETUP    = 2'b01,
        ACCESS   = 2'b10,
        RESPONSE = 2'b11
    } apb_state_e;

    // Watchdog FSM States
    typedef enum logic [1:0] {
        RUNNING = 2'b00,
        EXPIRED = 2'b01,
        RELOAD  = 2'b10
    } wdg_state_e;

    // APB FSM signals
    apb_state_e current_state, next_state;

    // Watchdog FSM signals
    wdg_state_e wdg_current_state, wdg_next_state;

    // Register storage
    logic [31:0] reload_val_reg;
    logic [31:0] current_val_reg;
    logic        ctrl_enable_reg;
    logic        ctrl_reset_enable_reg;
    logic        ctrl_int_enable_reg;
    logic [28:0] ctrl_reserved_reg;
    logic        wdg_expired;
    logic        int_pending;

    // Next state values
    logic [31:0] reload_val_next;
    logic [31:0] current_val_next;
    logic        ctrl_enable_next;
    logic        ctrl_reset_enable_next;
    logic        ctrl_int_enable_next;
    logic [28:0] ctrl_reserved_next;
    logic        wdg_expired_next;
    logic        int_pending_next;

    // Control signals
    logic        register_write_en;
    logic [7:0]  write_address;
    logic        reload_trigger;

    // Counter logic
    logic [31:0] decremented_val;
    logic        counter_zero;
    logic        counter_decrement;

    // Address decode
    logic addr_reload;
    logic addr_current;
    logic addr_ctrl;
    logic addr_reserved;

    assign addr_reload   = (paddr == ADDR_RELOAD_VAL);
    assign addr_current  = (paddr == ADDR_CURRENT_VAL);
    assign addr_ctrl     = (paddr == ADDR_CTRL);
    assign addr_reserved = (paddr == ADDR_RESERVED);

    // Counter logic
    assign decremented_val = current_val_reg - 1;
    assign counter_zero = (current_val_reg == 32'h0);
    assign counter_decrement = ctrl_enable_reg & !counter_zero;

    // APB FSM sequential logic
    always_ff @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // APB FSM combinational logic
    always_comb begin
        next_state = current_state; // Default assignment
        case (current_state)
            IDLE: begin
                if (psel)
                    next_state = SETUP;
            end
            SETUP: begin
                if (penable)
                    next_state = ACCESS;
            end
            ACCESS: begin
                next_state = RESPONSE;
            end
            RESPONSE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // APB control signals
    always_comb begin
        pready = 1'b0;
        pslverr = 1'b0;
        register_write_en = 1'b0;
        write_address = 8'h00;

        case (current_state)
            IDLE: ;
            SETUP: ;
            ACCESS: begin
                if (psel && penable) begin
                    register_write_en = pwrite;
                    write_address = paddr;
                end
            end
            RESPONSE: begin
                pready = 1'b1;
                if (psel && penable && pwrite && addr_reserved) begin
                    pslverr = 1'b1;
                end
            end
        endcase
    end

    // Read data multiplexer
    always_comb begin
        prdata = 32'h00000000;
        case (paddr)
            ADDR_RELOAD_VAL:  prdata = reload_val_reg;
            ADDR_CURRENT_VAL: prdata = current_val_reg;
            ADDR_CTRL:        prdata = {ctrl_reserved_reg, ctrl_int_enable_reg, ctrl_reset_enable_reg, ctrl_enable_reg};
            default:          prdata = 32'h00000000;
        endcase
    end

    // Register write logic
    always_ff @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            reload_val_reg <= 32'hFFFFFFFF;
            current_val_reg <= 32'hFFFFFFFF;
            ctrl_enable_reg <= 1'b0;
            ctrl_reset_enable_reg <= 1'b0;
            ctrl_int_enable_reg <= 1'b0;
            ctrl_reserved_reg <= 29'h0000000;
            wdg_expired <= 1'b0;
            int_pending <= 1'b0;
        end else if (register_write_en) begin
            unique case (write_address)
                ADDR_RELOAD_VAL: begin
                    reload_val_reg <= pwdata;
                    wdg_expired <= 1'b0; // Clear expiration on reload write
                end
                ADDR_CTRL: begin
                    ctrl_enable_reg <= pwdata[0];
                    ctrl_reset_enable_reg <= pwdata[1];
                    ctrl_int_enable_reg <= pwdata[2];
                    ctrl_reserved_reg <= pwdata[31:3];
                end
                default: ; // Do nothing for reserved or read-only registers
            endcase
        end else begin
            // Update registers with next values
            reload_val_reg <= reload_val_next;
            current_val_reg <= current_val_next;
            ctrl_enable_reg <= ctrl_enable_next;
            ctrl_reset_enable_reg <= ctrl_reset_enable_next;
            ctrl_int_enable_reg <= ctrl_int_enable_next;
            ctrl_reserved_reg <= ctrl_reserved_next;
            wdg_expired <= wdg_expired_next;
            int_pending <= int_pending_next;
        end
    end

    // Register next value logic
    always_comb begin
        // Default assignments
        reload_val_next = reload_val_reg;
        current_val_next = current_val_reg;
        ctrl_enable_next = ctrl_enable_reg;
        ctrl_reset_enable_next = ctrl_reset_enable_reg;
        ctrl_int_enable_next = ctrl_int_enable_reg;
        ctrl_reserved_next = ctrl_reserved_reg;
        wdg_expired_next = wdg_expired;
        int_pending_next = int_pending;

        // Counter update logic
        case (wdg_current_state)
            RUNNING: current_val_next = counter_decrement ? decremented_val : current_val_reg;
            EXPIRED: current_val_next = current_val_reg;  // Hold value when expired
            RELOAD:  current_val_next = reload_val_reg;   // Load new value
            default: current_val_next = current_val_reg;
        endcase

        // Expiration handling
        if (wdg_current_state == RUNNING && counter_zero && ctrl_enable_reg) begin
            wdg_expired_next = 1'b1;
            int_pending_next = 1'b1;
        end

        // Reload trigger handling
        if (reload_trigger) begin
            wdg_expired_next = 1'b0;
            int_pending_next = 1'b0;
        end
    end

    // Watchdog FSM sequential logic
    always_ff @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            wdg_current_state <= RUNNING;
        end else begin
            wdg_current_state <= wdg_next_state;
        end
    end

    // Reload trigger detection
    assign reload_trigger = (register_write_en && addr_reload) || wdg_expired;

    // Watchdog FSM combinational logic
    always_comb begin
        case (wdg_current_state)
            RUNNING: wdg_next_state = (counter_zero && ctrl_enable_reg) ? EXPIRED : RUNNING;
            EXPIRED: wdg_next_state = reload_trigger ? RELOAD : EXPIRED;
            RELOAD:  wdg_next_state = RUNNING;
            default: wdg_next_state = RUNNING;
        endcase
    end

    // Output generation
    assign wdg_rst_n = !(wdg_expired && ctrl_reset_enable_reg);
    assign irq = int_pending && ctrl_int_enable_reg;

endmodule

