// Transaction class
class Transaction;
    rand bit         psel;
    rand bit         penable;
    rand bit [7:0]   paddr;
    rand bit         pwrite;
    rand bit [31:0]  pwdata;

    constraint c_addr { paddr inside {[8'h00:8'h0C]}; }
    constraint c_valid_write { pwrite -> (paddr != 8'h04); } // Current val is read-only

    function void display(string name);
        $display("%s: psel=%b, penable=%b, paddr=0x%02h, pwrite=%b, pwdata=0x%08h", 
                 name, psel, penable, paddr, pwrite, pwdata);
    endfunction
endclass

// Driver class
class Driver;
    virtual interface apb_if vif;

    function new(virtual interface apb_if v);
        vif = v;
    endfunction

    task reset();
        vif.psel    <= 0;
        vif.penable <= 0;
        vif.paddr   <= 0;
        vif.pwrite  <= 0;
        vif.pwdata  <= 0;

        repeat(5) @(posedge vif.pclk);
        vif.preset_n <= 0;
        repeat(10) @(posedge vif.pclk);
        vif.preset_n <= 1;
        repeat(2) @(posedge vif.pclk);
    endtask

    task drive(Transaction t);
        @(posedge vif.pclk);
        vif.psel    <= t.psel;
        vif.paddr   <= t.paddr;
        vif.pwrite  <= t.pwrite;
        vif.pwdata  <= t.pwdata;

        if (t.psel) begin
            @(posedge vif.pclk);
            vif.penable <= 1;
            @(posedge vif.pclk);
            wait(vif.pready);
            @(posedge vif.pclk);
            vif.psel    <= 0;
            vif.penable <= 0;
        end
    endtask
endclass

// Monitor class
class Monitor;
    virtual interface apb_if vif;
    mailbox #(Transaction) apb_mbx;

    function new(virtual interface apb_if v, mailbox #(Transaction) m);
        vif = v;
        apb_mbx = m;
    endfunction

    task run();
        Transaction t;
        forever begin
            @(posedge vif.pclk);
            if (vif.psel && vif.penable && vif.pready) begin
                t = new();
                t.psel    = vif.psel;
                t.penable = vif.penable;
                t.paddr   = vif.paddr;
                t.pwrite  = vif.pwrite;
                t.pwdata  = vif.pwdata;
                apb_mbx.put(t);
            end
        end
    endtask
endclass

// Scoreboard class
class Scoreboard;
    mailbox #(Transaction) apb_mbx;

    bit [31:0] reload_val_reg;
    bit [31:0] current_val_reg;
    bit        ctrl_enable_reg;
    bit        ctrl_reset_enable_reg;
    bit        ctrl_int_enable_reg;
    bit        wdg_expired;
    bit        int_pending;

    int error_count;

    function new(mailbox #(Transaction) m);
        apb_mbx = m;
        reload_val_reg = 32'hFFFFFFFF;
        current_val_reg = 32'hFFFFFFFF;
        error_count = 0;
    endfunction

    task run();
        Transaction t;
        forever begin
            apb_mbx.get(t);

            if (t.pwrite) begin
                case (t.paddr)
                    8'h00: begin // RELOAD_VAL
                        reload_val_reg = t.pwdata;
                        wdg_expired = 0;
                    end
                    8'h08: begin // CTRL
                        ctrl_enable_reg = t.pwdata[0];
                        ctrl_reset_enable_reg = t.pwdata[1];
                        ctrl_int_enable_reg = t.pwdata[2];
                    end
                endcase
            end
        end
    endtask

    function void check_reset(bit rst_n);
        if (rst_n !== 1) begin
            $display("ERROR: Reset not asserted correctly");
            error_count++;
        end
    endfunction

    function void report();
        if (error_count == 0) 
            $display("TEST PASSED");
        else 
            $display("TEST FAILED with %0d errors", error_count);
    endfunction
