module apb_watchdog_timer_tb;
    logic pclk;
    logic preset_n;
    logic ext_clk;

    // Instantiate the interface
    apb_if intf(.pclk(pclk), .preset_n(preset_n));

    // Clock generation
    initial begin
        pclk = 0;
        forever #5 pclk = ~pclk;
    end

    // External clock generation
    initial begin
        ext_clk = 0;
        forever #10 ext_clk = ~ext_clk;
    end

    // Instantiate DUT
    apb_watchdog_timer dut (
        .pclk(intf.pclk),
        .preset_n(intf.preset_n),
        .ext_clk(ext_clk),
        .psel(intf.psel),
        .penable(intf.penable),
        .paddr(intf.paddr),
        .pwrite(intf.pwrite),
        .pwdata(intf.pwdata),
        .prdata(intf.prdata),
        .pready(intf.pready),
        .pslverr(intf.pslverr),
        .wdg_rst_n(intf.wdg_rst_n),
        .irq(intf.irq)
    );

    // Test program
    program test(apb_if vif);
        Driver drv;
        Monitor mon;
        Scoreboard scb;
        mailbox #(Transaction) apb_mbx;
        Transaction t;

        initial begin
            apb_mbx = new();
            drv = new(vif);
            mon = new(vif, apb_mbx);
            scb = new(apb_mbx);

            fork
                mon.run();
                scb.run();
            join_none

            // Reset sequence
            drv.reset();
            scb.check_reset(vif.preset_n);

            // Test 1: Write to reload register
            t = new();
            t.psel = 1;
            t.paddr = 8'h00;
            t.pwrite = 1;
            t.pwdata = 32'h000000FF;
            drv.drive(t);

            // Test 2: Write to control register
            t = new();
            t.psel = 1;
            t.paddr = 8'h08;
            t.pwrite = 1;
            t.pwdata = 32'h00000001; // Enable watchdog
            drv.drive(t);

            // Test 3: Read from reload register
            t = new();
            t.psel = 1;
            t.paddr = 8'h00;
            t.pwrite = 0;
            drv.drive(t);

            // Test 4: Read from current register
            t = new();
            t.psel = 1;
            t.paddr = 8'h04;
            t.pwrite = 0;
            drv.drive(t);

            // Test 5: Write to reserved address (should get pslverr)
            t = new();
            t.psel = 1;
            t.paddr = 8'h0C;
            t.pwrite = 1;
            t.pwdata = 32'hDEADBEEF;
            drv.drive(t);

            // Wait for some time to let watchdog run
            repeat(200) @(posedge vif.pclk);

            // Finish simulation
            scb.report();
            $finish;
        end
    endprogram

    // Instantiate test
    test t1(intf);

