module astroguard_tmr_spi (
    input  logic        clk,
    input  logic        clk_voter,
    input  logic        rst_n,

    output logic        spi_sclk,
    output logic        spi_mosi,
    input  logic        spi_miso,
    output logic        spi_cs_n,

    input  logic [7:0]  ctrl_config,
    input  logic [31:0] tx_data_a,
    input  logic [31:0] tx_data_b,
    input  logic [31:0] tx_data_c,
    input  logic        tx_start,
    output logic        tx_busy,
    output logic [31:0] rx_data_a,
    output logic [31:0] rx_data_b,
    output logic [31:0] rx_data_c,
    output logic        rx_valid,
    output logic [1:0]  error_status,

    input  logic        test_mode,
    input  logic [3:0]  test_select,
    output logic [31:0] diag_status
);

    // FSM State Types
    typedef enum logic [3:0] {
        IDLE        = 4'b0000,
        CONFIG      = 4'b0001,
        TX_SETUP    = 4'b0010,
        CLK_PHASE0  = 4'b0011,
        CLK_PHASE1  = 4'b0100,
        RX_CAPTURE  = 4'b0101,
        VOTE_CALC   = 4'b0110,
        ERROR_CHECK = 4'b0111,
        TX_COMPLETE = 4'b1000,
        ERROR_HAND  = 4'b1001
    } spi_state_e;

    typedef enum logic [1:0] {
        CLK_IDLE    = 2'b00,
        CLK_HIGH    = 2'b01,
        CLK_LOW     = 2'b10,
        CLK_TRANS   = 2'b11
    } clk_state_e;

    // Internal Registers
    logic [7:0]  config_reg;
    logic [7:0]  ctrl_reg;
    logic [7:0]  status_reg;

    logic [31:0] tx_shift_a;
    logic [31:0] tx_shift_b;
    logic [31:0] tx_shift_c;
    logic [31:0] rx_shift_a;
    logic [31:0] rx_shift_b;
    logic [31:0] rx_shift_c;

    logic        tx_vote_out;
    logic        rx_vote_in;
    logic        vote_error;
    logic [2:0]  channel_mask;

    logic [4:0]  bit_counter;
    logic [7:0]  clk_divider;
    logic [7:0]  clk_prescale;

    // FSM States
    spi_state_e fsm_state, next_fsm_state;
    clk_state_e clk_state, next_clk_state;

    // Clock Generation Signals
    logic sclk_int;

    // Combinational Logic Outputs
    assign spi_sclk = sclk_int;
    assign spi_cs_n = (fsm_state == IDLE || fsm_state == TX_COMPLETE || fsm_state == ERROR_HAND) ? 1'b1 : 1'b0;
    assign spi_mosi = tx_vote_out;
    assign rx_vote_in = spi_miso;

    // Sequential Logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            config_reg     <= 8'h00;
            ctrl_reg       <= 8'h00;
            status_reg     <= 8'h00;

            tx_shift_a     <= 32'h00000000;
            tx_shift_b     <= 32'h00000000;
            tx_shift_c     <= 32'h00000000;
            rx_shift_a     <= 32'h00000000;
            rx_shift_b     <= 32'h00000000;
            rx_shift_c     <= 32'h00000000;

            tx_vote_out    <= 1'b0;
            vote_error     <= 1'b0;
            channel_mask   <= 3'b000;

            bit_counter    <= 5'd0;
            clk_divider    <= 8'd0;
            clk_prescale   <= 8'd0;

            fsm_state      <= IDLE;
            clk_state      <= CLK_IDLE;

            sclk_int       <= 1'b0;
        end else begin
            config_reg     <= ctrl_config;
            ctrl_reg       <= ctrl_config;

            case (fsm_state)
                TX_SETUP: begin
                    tx_shift_a <= tx_data_a;
                    tx_shift_b <= tx_data_b;
                    tx_shift_c <= tx_data_c;
                end
                CLK_PHASE1: begin
                    tx_shift_a <= {tx_shift_a[30:0], 1'b0};
                    tx_shift_b <= {tx_shift_b[30:0], 1'b0};
                    tx_shift_c <= {tx_shift_c[30:0], 1'b0};
                end
                RX_CAPTURE: begin
                    rx_shift_a <= {rx_shift_a[30:0], rx_vote_in};
                    rx_shift_b <= {rx_shift_b[30:0], rx_vote_in};
                    rx_shift_c <= {rx_shift_c[30:0], rx_vote_in};
                end
                TX_COMPLETE: begin
                    rx_data_a <= rx_shift_a;
                    rx_data_b <= rx_shift_b;
                    rx_data_c <= rx_shift_c;
                end
                default: ;
            endcase

            case (clk_state)
                CLK_HIGH: sclk_int <= 1'b1;
                CLK_LOW:  sclk_int <= 1'b0;
                default:  sclk_int <= sclk_int;
            endcase

            // Update FSM states
            fsm_state <= next_fsm_state;
            clk_state <= next_clk_state;

            // Update counters
            if (fsm_state == CLK_PHASE0 || fsm_state == CLK_PHASE1) begin
                bit_counter <= bit_counter + 1;
            end else if (fsm_state == TX_COMPLETE) begin
                bit_counter <= 5'd0;
            end

            // Update clock divider
            if (clk_prescale == clk_divider) begin
                clk_prescale <= 8'd0;
            end else begin
                clk_prescale <= clk_prescale + 1;
            end
        end
    end

    // Combinational Logic for Next State
    always_comb begin
        next_fsm_state = fsm_state;
        next_clk_state = clk_state;
        tx_busy = 1'b1;
        rx_valid = 1'b0;
        error_status = 2'b00;
        vote_error = 1'b0;
        tx_vote_out = 1'b0;

        case (fsm_state)
            IDLE: begin
                tx_busy = 1'b0;
                if (tx_start) begin
                    next_fsm_state = CONFIG;
                end
            end

            CONFIG: begin
                clk_divider = config_reg[7:0];
                next_fsm_state = TX_SETUP;
            end

            TX_SETUP: begin
                next_fsm_state = CLK_PHASE0;
                next_clk_state = CLK_LOW;
            end

            CLK_PHASE0: begin
                // Sample phase
                next_clk_state = CLK_HIGH;
                tx_vote_out = (tx_shift_a[31] & tx_shift_b[31]) |
                              (tx_shift_b[31] & tx_shift_c[31]) |
                              (tx_shift_a[31] & tx_shift_c[31]);
            end

            CLK_PHASE1: begin
                // Shift phase
                next_clk_state = (bit_counter == 5'd31) ? CLK_IDLE : CLK_LOW;
                next_fsm_state = (bit_counter == 5'd31) ? RX_CAPTURE : CLK_PHASE0;
            end

            RX_CAPTURE: begin
                next_fsm_state = VOTE_CALC;
            end

            VOTE_CALC: begin
                // Simple majority voting for error detection
                vote_error = (rx_shift_a != rx_shift_b) ||
                             (rx_shift_b != rx_shift_c) ||
                             (rx_shift_a != rx_shift_c);
                next_fsm_state = ERROR_CHECK;
            end

            ERROR_CHECK: begin
                if (vote_error) begin
                    error_status = 2'b01; // TMR_MISMATCH
                    next_fsm_state = ERROR_HAND;
                end else begin
                    next_fsm_state = TX_COMPLETE;
                end
            end

            TX_COMPLETE: begin
                rx_valid = 1'b1;
                next_fsm_state = IDLE;
            end

            ERROR_HAND: begin
                error_status = 2'b10; // FATAL_ERR
                next_fsm_state = IDLE;
            end
        endcase

        // Handle clock transitions
        if (clk_prescale == clk_divider && fsm_state inside {CLK_PHASE0, CLK_PHASE1}) begin
            case (clk_state)
                CLK_LOW:   next_clk_state = CLK_HIGH;
                CLK_HIGH:  next_clk_state = CLK_LOW;
                default:   next_clk_state = clk_state;
            endcase
        end
    end

    // Diagnostic Status (simplified)
    always_comb begin
        diag_status = 32'h00000000;
        if (test_mode) begin
            case (test_select)
                4'h0: diag_status = {24'h000000, fsm_state};
                4'h1: diag_status = {24'h000000, clk_state};
                4'h2: diag_status = {1'b0, vote_error, 16'h0000, bit_counter};
                4'h3: diag_status = {8'h00, ctrl_reg, 8'h00, status_reg};
                default: diag_status = 32'hDEADBEEF;
            endcase
        end
    end

endmodule

