localparam CLK_PHASE0  = 4'h3;
localparam CLK_PHASE1  = 4'h4;
localparam RX_CAPTURE  = 4'h5;
localparam VOTE_CALC   = 4'h6;
localparam ERROR_CHECK = 4'h7;
localparam TX_COMPLETE = 4'h8;
localparam ERROR_HAND  = 4'h9;

