reg [7:0]  clk_divider;
reg [7:0]  clk_prescale;
reg [3:0]  fsm_state;
reg [1:0]  clk_fsm_state;

// Internal signals
reg        sclk_en;
reg        sample_phase;
reg        shift_phase;
wire       clk_tick;

// Clock divider logic
assign clk_tick = (clk_prescale == 8'd0);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        clk_prescale <= 8'd0;
    end else if (sclk_en) begin
        if (clk_tick)
            clk_prescale <= clk_divider;
        else
            clk_prescale <= clk_prescale - 1'b1;
    end else begin
        clk_prescale <= clk_divider;
