                tx_shift_b <= tx_data_b;
                tx_shift_c <= tx_data_c;
                rx_shift_a <= 32'h0;
                rx_shift_b <= 32'h0;
                rx_shift_c <= 32'h0;
                bit_counter <= 5'd31;
                spi_cs_n <= 1'b0;
                sclk_en <= 1'b1;
                fsm_state <= CLK_PHASE0;
            end

            CLK_PHASE0: begin
                sample_phase <= 1'b1;
                shift_phase <= 1'b0;
                if (clk_tick) begin
                    spi_sclk <= 1'b1;
                    fsm_state <= CLK_PHASE1;
                end
            end

            CLK_PHASE1: begin
                sample_phase <= 1'b0;
                shift_phase <= 1'b1;
                if (clk_tick) begin
                    spi_sclk <= 1'b0;

                    // Shift data
                    tx_shift_a <= {tx_shift_a[30:0], 1'b0};
                    tx_shift_b <= {tx_shift_b[30:0], 1'b0};
                    tx_shift_c <= {tx_shift_c[30:0], 1'b0};

                    // Capture MISO data
                    rx_shift_a <= {rx_shift_a[30:0], spi_miso};
                    rx_shift_b <= {rx_shift_b[30:0], spi_miso};
                    rx_shift_c <= {rx_shift_c[30:0], spi_miso};

                    if (bit_counter == 5'd0) begin
                        fsm_state <= VOTE_CALC;
                    end else begin
                        bit_counter <= bit_counter - 1'b1;
                        fsm_state <= CLK_PHASE0;
                    end
                end
            end

            VOTE_CALC: begin
                // Majority vote for transmitted bit
                tx_vote_out <= (tx_shift_a[31] & tx_shift_b[31]) |
                               (tx_shift_b[31] & tx_shift_c[31]) |
                               (tx_shift_a[31] & tx_shift_c[31]);

                // Majority vote for received bit
                rx_vote_in <= (rx_shift_a[0] & rx_shift_b[0]) |
                              (rx_shift_b[0] & rx_shift_c[0]) |
                              (rx_shift_a[0] & rx_shift_c[0]);

                // Check for voting error
                vote_error <= (rx_shift_a[0] != rx_shift_b[0]) ||
                              (rx_shift_b[0] != rx_shift_c[0]) ||
                              (rx_shift_a[0] != rx_shift_c[0]);

                fsm_state <= ERROR_CHECK;
            end

            ERROR_CHECK: begin
                if (vote_error) begin
                    error_status <= 2'b01; // TMR_MISMATCH
                    fsm_state <= ERROR_HAND;
                end else begin
                    error_status <= 2'b00; // OK
                    fsm_state <= TX_COMPLETE;
                end
