            TX_COMPLETE: begin
                rx_data_a <= rx_shift_a;
                rx_data_b <= rx_shift_b;
                rx_data_c <= rx_shift_c;
                rx_valid <= 1'b1;
                sclk_en <= 1'b0;
                fsm_state <= IDLE;
            end

            ERROR_HAND: begin
                // In error handling state, we still complete the transfer
                // but indicate the error
                rx_data_a <= rx_shift_a;
                rx_data_b <= rx_shift_b;
                rx_data_c <= rx_shift_c;
                rx_valid <= 1'b1;
                sclk_en <= 1'b0;
                fsm_state <= IDLE;
            end

            default: begin
                fsm_state <= IDLE;
            end
        endcase
    end
