    // DMA Control Register (offset 0x1C)
    logic               dma_start;
    logic               dma_write;      // 1 = write, 0 = read
    logic               dma_active;

    // TX FIFO signals
    logic               tx_fifo_wren;
    logic               tx_fifo_full;
    logic               tx_fifo_empty;
    logic [31:0]        tx_fifo_rdata;
    logic [31:0]        tx_fifo_mem [FIFO_DEPTH-1:0];
    logic [$clog2(FIFO_DEPTH)-1:0] tx_fifo_wptr;
    logic [$clog2(FIFO_DEPTH)-1:0] tx_fifo_rptr;

    // RX FIFO signals
    logic               rx_fifo_wren;
    logic               rx_fifo_full;
    logic               rx_fifo_empty;
    logic [31:0]        rx_fifo_wdata;
    logic [31:0]        rx_fifo_mem [FIFO_DEPTH-1:0];
    logic [$clog2(FIFO_DEPTH)-1:0] rx_fifo_wptr;
    logic [$clog2(FIFO_DEPTH)-1:0] rx_fifo_rptr;

    // Command and Transfer State
    logic [31:0]        cmd_len;
    logic               cmd_valid;
    logic               is_tx;          // 1 = transmit, 0 = receive
    logic [5:0]         bit_cnt;
    logic               shift_enable;   // when 1, shift register updates
    logic [31:0]        shift_reg;
    logic               miso_capture;

    // Clock Divider
    logic [$clog2(256)-1:0] clk_div_cnt;
    logic                   sclk_toggle;
    logic [31:0]            sclk_int;   // internal SPI clock before registration

    // Interrupt & DMA
    logic               intr_pending;
    logic               dma_req_int;

    // Internal FSM
    state_t             cur_state, next_state;

    //====================================================================
    //  FIFO Implementation
    //====================================================================
    // TX FIFO write
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_fifo_mem <= '{default: '0};
            tx_fifo_wptr <= '0;
            tx_fifo_rptr <= '0;
            tx_fifo_full <= 1'b0;
            tx_fifo_empty <= 1'b1;
        end else begin
            if (tx_fifo_wren && !tx_fifo_full) begin
                tx_fifo_mem[tx_fifo_wptr] <= tx_fifo_din;
                tx_fifo_wptr <= tx_fifo_wptr + 1'b1;
                tx_fifo_full <= (tx_fifo_wptr + 1'b1 == tx_fifo_rptr);
                tx_fifo_empty <= 1'b0;
            end
            // APB read side (handled elsewhere)
        end
    end

    // TX FIFO read (APB read data mux)
    always_comb begin
        if (apb_pwrite == 1'b0 && apb_psel && apb_penable) begin
            case (apb_paddr[7:2])
                3'h3: apb_prdata = tx_fifo_rdata; // dummy, not used
                default: apb_prdata = '0;
            endcase
        end else begin
            apb_prdata = '0;
        end
    end

    assign tx_fifo_rdata = tx_fifo_mem[tx_fifo_rptr];

    // TX FIFO read pointer update (when read by APB)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_fifo_rptr <= '0;
        end else if (apb_pwrite == 1'b0 && apb_psel && apb_penable && (apb_paddr == 8'h10)) begin
            // No read from TX FIFO in this design
        end
    end

    // TX FIFO full/empty flags
    assign tx_fifo_full  = (tx_fifo_wptr + 1'b1 == tx_fifo_rptr);
    assign tx_fifo_empty = (tx_fifo_wptr == tx_fifo_rptr);

    // RX FIFO write
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_fifo_mem <= '{default: '0};
            rx_fifo_wptr <= '0;
            rx_fifo_rptr <= '0;
            rx_fifo_full <= 1'b0;
            rx_fifo_empty <= 1'b1;
        end else begin
            if (rx_fifo_wren && !rx_fifo_full) begin
                rx_fifo_mem[rx_fifo_wptr] <= rx_fifo_wdata;
                rx_fifo_wptr <= rx_fifo_wptr + 1'b1;
                rx_fifo_full <= (rx_fifo_wptr + 1'b1 == rx_fifo_rptr);
                rx_fifo_empty <= 1'b0;
            end
            // APB read side (handled elsewhere)
        end
    end

    // RX FIFO read (APB read data)
    always_comb begin
        if (apb_pwrite == 1'b0 && apb_psel && apb_penable) begin
            case (apb_paddr[7:2])
                3'h2: apb_prdata = rx_fifo_mem[rx_fifo_rptr]; // dummy
                3'h3: apb_prdata = rx_fifo_mem[rx_fifo_rptr]; // actual data read
                default: apb_prdata = '0;
            endcase
        end else begin
            apb_prdata = '0;
        end
    end

    // RX FIFO read pointer update (when APB reads)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_fifo_rptr <= '0;
        end else if (apb_pwrite == 1'b0 && apb_psel && apb_penable && (apb_paddr == 8'h10)) begin
            rx_fifo_rptr <= rx_fifo_rptr + 1'b1;
            rx_fifo_empty <= (rx_fifo_rptr + 1'b1 == rx_fifo_wptr);
        end
    end

    assign rx_fifo_full  = (rx_fifo_wptr + 1'b1 == rx_fifo_rptr);
    assign rx_fifo_empty = (rx_fifo_wptr == rx_fifo_rptr);
    assign rx_fifo_dout  = rx_fifo_mem[rx_fifo_rptr];

    //====================================================================
    //  APB Register File
    //====================================================================
    // Address decoding
    localparam int REG_CTRL        = 8'h00;
    localparam int REG_INTMASK     = 8'h04;
    localparam int REG_STATUS      = 8'h08;
    localparam int REG_TXFIFO_WDATA= 8'h0C;
    localparam int REG_RXFIFO_RDATA= 8'h10;
    localparam int REG_DMA_ADDR    = 8'h14;
    localparam int REG_DMA_LEN     = 8'h18;
    localparam int REG_DMA_CTRL    = 8'h1C;

    // Write side
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ctrl_en          <= 1'b0;
            ctrl_cpol        <= 1'b0;
            ctrl_cpha       <= 1'b0;
            ctrl_dma_en     <= 1'b0;
            ctrl_int_en     <= 1'b0;
            ctrl_fifo_depth_0 <= 1'b0;
            ctrl_fifo_depth_1 <= 1'b0;
            ctrl_start      <= 1'b0;
            ctrl_xfer_mode  <= 1'b0;
            intmask_txuf    <= 4'h0;
            intmask_rxof    <= 4'h0;
            intmask_done    <= 4'h0;
            intmask_err     <= 4'h0;
            dma_len         <= '0;
            dma_start       <= 1'b0;
            dma_write       <= 1'b0;
        end else if (apb_pwrite && apb_psel && apb_penable) begin
            case (apb_paddr[7:2])
                REG_CTRL: begin
                    if (apb_pstrb[0]) ctrl_en          <= apb_pwdata[0];
                    if (apb_pstrb[1]) ctrl_cpol        <= apb_pwdata[1];
                    if (apb_pstrb[2]) ctrl_cpha        <= apb_pwdata[2];
                    if (apb_pstrb[3]) ctrl_dma_en      <= apb_pwdata[3];
                    if (apb_pstrb[4]) ctrl_int_en      <= apb_pwdata[4];
                    if (apb_pstrb[5]) ctrl_fifo_depth_0 <= apb_pwdata[5];
                    if (apb_pstrb[6]) ctrl_fifo_depth_1 <= apb_pwdata[6];
                    if (apb_pstrb[7]) ctrl_start       <= apb_pwdata[7];
                end
                REG_INTMASK: begin
                    if (apb_pstrb[0]) intmask_txuf <= apb_pwdata[0];
                    if (apb_pstrb[1]) intmask_rxof <= apb_pwdata[1];
                    if (apb_pstrb[2]) intmask_done <= apb_pwdata[2];
                    if (apb_pstrb[3]) intmask_err  <= apb_pwdata[3];
                end
                REG_STATUS: begin
                    // Read‑only, no write
                end
                REG_TXFIFO_WDATA: begin
                    // Write data into TX FIFO via tx_fifo_wen (external)
                end
                REG_RXFIFO_RDATA: begin
                    // Read data from RX FIFO (no write)
                end
                REG_DMA_ADDR: begin
                    if (apb_pstrb[0]) dma_addr <= apb_pwdata[31:0];
                end
                REG_DMA_LEN: begin
                    if (apb_pstrb[0]) dma_len <= apb_pwdata[31:0];
                end
                REG_DMA_CTRL: begin
                    if (apb_pstrb[0]) dma_start <= apb_pwdata[0];
                    if (apb_pstrb[1]) dma_write <= apb_pwdata[1];
                end
                default: begin
                    apb_pslverr <= 1'b1;
                end
            endcase
            apb_pslverr <= 1'b0;
        end
    end

    // Read side
    always_comb begin
        if (apb_pwrite == 1'b0 && apb_psel && apb_penable) begin
            case (apb_paddr[7:2])
                REG_CTRL:      apb_prdata = {31'b0, ctrl_en};
                REG_INTMASK:   apb_prdata = {30'b0, intmask_txuf, intmask_rxof, intmask_done, intmask_err};
                REG_STATUS:    apb_prdata = {status_txfull, status_txempty,
                                            status_rxfull, status_rxempty,
                                            status_xfer_done, status_error, 1'b0, 1'b0};
                REG_RXFIFO_RDATA: begin
                    // Return latest RX FIFO data
                    apb_prdata = rx_fifo_dout;
                end
                REG_DMA_ADDR:  apb_prdata = dma_addr;
                REG_DMA_LEN:   apb_prdata = dma_len;
                REG_DMA_CTRL:  apb_prdata = {31'b0, dma_start, dma_write};
                default:       apb_prdata = '0;
            endcase
        end else begin
            apb_prdata = '0;
        end
    end

    // APB ready and error
    assign apb_pready = 1'b1;
    assign apb_pslverr = 1'b0;

    //====================================================================
    //  Interrupt Handling
    //====================================================================
    // Pending interrupt flag (latched)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            intr_pending <= 1'b0;
        end else begin
            // Set on error, overflow, underflow, or transfer done
            if (status_error)        intr_pending <= 1'b1;
            if (status_rxfull)       intr_pending <= 1'b1;
            if (status_txempty)      intr_pending <= 1'b1;
            if (status_xfer_done)    intr_pending <= 1'b1;
            // Clear on read of STATUS register (automatic clear by APB read)
        end
    end

    // Interrupt output (edge‑triggered style)
    assign intr = (intr_pending & {4{ctrl_int_en}}) ? 1'b1 : 1'b0;

    //====================================================================
    //  Clock Divider (generates SPI clock)
    //====================================================================
    // Assume system clock frequency is such that divisor 1‑256 is valid
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div_cnt <= '0;
            sclk_toggle <= 1'b0;
        end else if (apb_pclk) begin
            if (clk_div_cnt == ( (ctrl_fifo_depth_1 ? 255 : 1) - 1 )) begin
                clk_div_cnt <= '0;
                sclk_toggle <= ~sclk_toggle;
            end else begin
                clk_div_cnt <= clk_div_cnt + 1'b1;
            end
        end
    end

    // Register the SPI clock before driving it
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) spi_clk <= 1'b0;
        else        spi_clk <= sclk_toggle;
    end

    //====================================================================
    //  FSM – State Register
    //====================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) cur_state <= S_IDLE;
        else        cur_state <= next_state;
    end

    //====================================================================
    //  FSM – Next‑State Logic
    //====================================================================
    always_comb begin
        // Default next state
        next_state = cur_state;

        case (cur_state)
            S_IDLE: begin
                if (spi_mst_en && ctrl_start) next_state = S_SETUP;
            end
            S_SETUP: next_state = S_TX; // always go to TX (full‑duplex)
            S_TX:    if (bit_cnt == cmd_len-1) next_state = S_WAIT;
            S_RX:    if (bit_cnt == cmd_len-1) next_state = S_WAIT;
            S_WAIT: if (spi_cs_n == 1'b1) next_state = S_DONE;
            S_ERROR: next_state = S_IDLE;
            S_DONE:  if (!dma_start) next_state = S_IDLE; // wait for next start
