    //  FSM – Control Signal Generation
    //====================================================================
    // CPOL/CPHA handling
    logic sclk_level;
    logic sclk_rising, sclk_falling;
    logic data_out_edge, data_in_edge;

    // Determine current SCLK level (idle level = CPOL)
    assign sclk_level = (cur_state == S_SETUP) ? cpol_cfg : sclk_toggle;

    // Edge detection (previous level needed)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk_prev <= 1'b0;
        end else begin
            sclk_prev <= sclk_level;
        end
    end

    assign sclk_rising  = (sclk_prev == 1'b0) && (sclk_level == 1'b1);
    assign sclk_falling = (sclk_prev == 1'b1) && (sclk_level == 1'b0);

    // Data out edge according to CPHA
    assign data_out_edge = (cpha_cfg == 1'b0) ? sclk_rising : sclk_falling;
    // Data in edge according to CPHA
    assign data_in_edge  = (cpha_cfg == 1'b0) ? sclk_falling : sclk_rising;

    //====================================================================
    //  FSM – State Specific Logic
    //====================================================================
    // Control signals for each state
    logic cs_n;
    logic tx_fifo_wren_int;
    logic rx_fifo_wren_int;
    logic shift_reg_load;
    logic shift_reg_shift;
    logic bit_cnt_load;
    logic bit_cnt_en;
    logic cmd_len_load;
    logic is_tx_reg;

    // Default assignments
    assign cs_n      = (cur_state == S_SETUP) ? 1'b0 : 1'b1;
    assign spi_cs_n  = cs_n;
    assign spi_mosi  = (cur_state == S_TX) && data_out_edge ? shift_reg[bit_cnt] : 1'b0;
    assign spi_clk   = sclk_level; // already registered

    // Load shift register from TX FIFO (or zero for RX‑only)
    always_comb begin
        if (shift_reg_load) begin
            if (is_tx_reg) shift_reg = tx_fifo_rdata;
            else           shift_reg = '0;
        end else begin
            shift_reg = shift_reg;
        end
    end

    // Bit counter
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) bit_cnt <= '0;
        else if (bit_cnt_load) bit_cnt <= '0;
        else if (shift_reg_shift) bit_cnt <= bit_cnt + 1'b1;
    end

