    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) cmd_len <= '0;
        else if (cmd_len_load) cmd_len <= dma_len;
    end

    // Direction register (TX vs RX)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) is_tx_reg <= 1'b1;
        else        is_tx_reg <= (cur_state == S_SETUP) ? ctrl_xfer_mode : is_tx_reg;
    end

    //====================================================================
    //  State Machine Sequential Logic
    //====================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_state          <= S_IDLE;
            tx_fifo_wren_int   <= 1'b0;
            rx_fifo_wren_int   <= 1'b0;
            shift_reg_load     <= 1'b0;
            shift_reg_shift    <= 1'b0;
            bit_cnt_load       <= 1'b0;
            bit_cnt_en         <= 1'b0;
            cmd_len_load       <= 1'b0;
            is_tx_reg          <= 1'b0;
            status_txfull      <= 1'b0;
            status_txempty     <= 1'b1;
            status_rxfull      <= 1'b0;
            status_rxempty     <= 1'b1;
            status_xfer_done   <= 1'b0;
            status_error       <= 1'b0;
            dma_req_int        <= 1'b0;
        end else begin
            case (cur_state)
                S_IDLE: begin
                    // Clear status flags
                    status_txfull   <= 1'b0;
                    status_txempty  <= 1'b1;
                    status_rxfull   <= 1'b0;
                    status_rxempty  <= 1'b1;
                    status_xfer_done<= 1'b0;
                    status_error    <= 1'b0;
                    dma_req_int     <= 1'b0;
                end
                S_SETUP: begin
                    // Load transfer length
                    cmd_len_load <= 1'b1;
                    // Determine direction
                    is_tx_reg    <= (ctrl_xfer_mode == 1'b1); // simple mapping
                end
                S_TX: begin
                    // Drive MOSI on data_out_edge
                    if (data_out_edge) begin
                        // Load next word from TX FIFO if not empty
                        tx_fifo_wren_int <= !tx_fifo_empty;
                    end
                    // Shift register shift enable
                    shift_reg_shift <= data_out_edge;
                    // Bit counter enable
                    bit_cnt_en <= data_out_edge;
                    // If we reached the last bit, prepare to wait
                    if (bit_cnt == cmd_len-1) begin
                        // De‑assert CS
                        cs_n <= 1'b1;
                    end
                end
                S_RX: begin
                    // Capture MISO on data_in_edge
                    if (data_in_edge) begin
                        miso_capture <= spi_miso;
                    end
                    // Write captured data into RX FIFO if not full
                    if (data_in_edge && !rx_fifo_full) begin
                        rx_fifo_wren_int <= 1'b1;
                        rx_fifo_wdata  <= miso_capture;
                    end
                    // Shift enable & bit counter
                    shift_reg_shift <= data_in_edge;
                    bit_cnt_en <= data_in_edge;
                end
                S_WAIT: begin
                    // Update status flags
                    status_txfull   <= tx_fifo_full;
                    status_txempty  <= tx_fifo_empty;
                    status_rxfull   <= rx_fifo_full;
                    status_rxempty  <= rx_fifo_empty;
                    status_xfer_done<= 1'b1;
                    status_error    <= 1'b0;
                    // Generate DMA request if transfer is active and FIFO not empty/full
                    dma_req_int <= (cur_state inside {S_TX, S_RX}) &&
                                   ((is_tx_reg && !tx_fifo_empty) || (!is_tx_reg && !rx_fifo_full));
                end
                S_ERROR: begin
                    // Latch error flag
                    status_error <= 1'b1;
                    // Reset FSM
                    cur_state    <= S_IDLE;
                end
                S_DONE: begin
                    // Clear xfer_done so next transfer can be signaled
                    status_xfer_done <= 1'b0;
                    // If another transfer is pending (dma_start), go back to SETUP
                    if (dma_start) cur_state <= S_SETUP;
                    else          cur_state <= S_IDLE;
                end
            endcase
        end
    end

    //====================================================================
    //  Output Assignments
    //====================================================================
    assign dma_req = dma_req_int;
    assign status  = {status_txfull, status_txempty, status_rxfull, status_rxempty};

    //====================================================================
    //  TX FIFO Write Enable (external)
    //====================================================================
    assign tx_fifo_wren = tx_fifo_wen; // external write enable

    //====================================================================
    //  RX FIFO Write Enable (internal)
    //====================================================================
    assign rx_fifo_wren = rx_fifo_wren_int;

    //====================================================================
    //  End of Module
    //====================================================================
endmodule

