    assign sclk_falling = (sclk_prev == 1'b1) && (sclk_level == 1'b0);

    // Data out edge according to CPHA
    assign data_out_edge = (cpha_cfg == 1'b0) ? sclk_rising : sclk_falling;
    // Data in edge according to CPHA
    assign data_in_edge  = (cpha_cfg == 1'b0) ? sclk_falling : sclk_rising;

    //====================================================================
    //  FSM – State Specific Logic
    //====================================================================
    // Control signals for each state
    logic cs_n;
    logic tx_fifo_wren_int;
    logic rx_fifo_wren_int;
    logic shift_reg_load;
    logic shift_reg_shift;
    logic bit_cnt_load;
    logic bit_cnt_en;
    logic cmd_len_load;
    logic is_tx_reg;

