    assign cs_n      = (cur_state == S_SETUP) ? 1'b0 : 1'b1;
    assign spi_cs_n  = cs_n;
    assign spi_mosi  = (cur_state == S_TX) && data_out_edge ? shift_reg[bit_cnt] : 1'b0;
    assign spi_clk   = sclk_level; // already registered

    // Load shift register from TX FIFO (or zero for RX‑only)
    always_comb begin
        if (shift_reg_load) begin
            if (is_tx_reg) shift_reg = tx_fifo_rdata;
            else           shift_reg = '0;
        end else begin
            shift_reg = shift_reg;
        end
    end

    // Bit counter
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) bit_cnt <= '0;
        else if (bit_cnt_load) bit_cnt <= '0;
        else if (shift_reg_shift) bit_cnt <= bit_cnt + 1'b1;
    end

