        S_IDLE,
        S_SETUP,
        S_TX,
        S_RX,
        S_WAIT,
        S_ERROR,
        S_DONE
    } state_t;

    //====================================================================
    //  Register Definitions
    //====================================================================
    // Control Register (offset 0x00)
    logic               ctrl_en;
    logic               ctrl_cpol;
    logic               ctrl_cpha;
    logic               ctrl_dma_en;
    logic               ctrl_int_en;
    logic               ctrl_fifo_depth_0;
    logic               ctrl_fifo_depth_1;
    logic               ctrl_start;
    logic               ctrl_xfer_mode;   // 0: TX, 1: RX, 1: both (unused)

    // Interrupt Mask Register (offset 0x04)
    logic [3:0]         intmask_txuf;
    logic [3:0]         intmask_rxof;
    logic [3:0]         intmask_done;
    logic [3:0]         intmask_err;

