`timescale 1ns/1ps
module complex_apb_spi (
    // APB slave interface
    input  clk,
    input  rst_n,
    input  apb_pclk,
    input  apb_psel,
    input  apb_penable,
    input  apb_pwrite,
    input  [7:0] apb_paddr,
    input  [31:0] apb_pwdata,
    input  [3:0] apb_pstrb,
    output [31:0] apb_prdata,
    output       apb_pready,
    output       apb_pslverr,
    // SPI master interface
    input        spi_mst_en,
    output       spi_clk,
    input        spi_miso,
    output       spi_mosi,
    output       spi_cs_n,
    // Configuration inputs
    input        cpol_cfg,
    input        cpha_cfg,
    // FIFO interface
    input      [31:0] tx_fifo_din,
    input        tx_fifo_wen,
    output     [31:0] rx_fifo_dout,
    output       rx_fifo_full,
    output       rx_fifo_empty,
    // Control / status
    output       intr,
    output       dma_req,
    output [3:0] status
);
    // -----------------------------------------------------------------
    // Parameters and address definitions
    // -----------------------------------------------------------------
    localparam FIFO_DEPTH = 32;
    localparam DATA_WIDTH = 32;
    localparam ADDR_CTRL        = 8'h00;
    localparam ADDR_INTMASK     = 8'h04;
    localparam ADDR_STATUS      = 8'h08;
    localparam ADDR_TXFIFO_WDATA= 8'h0C;
    localparam ADDR_RXFIFO_RDATA= 8'h10;
    localparam ADDR_DMA_ADDR    = 8'h14;
    localparam ADDR_DMA_LEN     = 8'h18;
    localparam ADDR_DMA_CTRL    = 8'h1C;

    // FSM state encoding (3‑bit)
    localparam S_IDLE   = 3'b000;
    localparam S_SETUP  = 3'b001;
    localparam S_TX     = 3'b010;
    localparam S_RX     = 3'b011;
    localparam S_WAIT   = 3'b100;
    localparam S_ERROR  = 3'b101;
    localparam S_DONE   = 3'b110;

    // -----------------------------------------------------------------
    // Register file (APB registers)
    // -----------------------------------------------------------------
    reg [31:0] reg_ctrl;
    reg [31:0] reg_intmask;
    reg [31:0] reg_status;
    reg [31:0] reg_dma_addr;
    reg [31:0] reg_dma_len;
    reg [31:0] reg_dma_ctrl;

    // -----------------------------------------------------------------
    // TX FIFO (write‑only from APB, read‑only by shift engine)
    // -----------------------------------------------------------------
    reg [DATA_WIDTH-1:0] tx_fifo_mem [0:FIFO_DEPTH-1];
    reg [5:0]            tx_wr_ptr;
    reg [5:0]            tx_rd_ptr;
    reg                  tx_fifo_full;
    reg                  tx_fifo_empty;
    reg                  tx_fifo_rden;      // read enable for shift engine
    reg [DATA_WIDTH-1:0] tx_fifo_dout;      // data read from FIFO

    // -----------------------------------------------------------------
    // RX FIFO (write‑only by shift engine, read‑only by APB)
    // -----------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rx_fifo_mem [0:FIFO_DEPTH-1];
    reg [5:0]            rx_wr_ptr;
    reg [5:0]            rx_rd_ptr;
    reg                  rx_fifo_full;
    reg                  rx_fifo_empty;
    reg                  rx_fifo_wren;      // write enable for shift engine
    reg [DATA_WIDTH-1:0] rx_fifo_dout;      // data to be read by APB

    // -----------------------------------------------------------------
    // Shift engine signals
    // -----------------------------------------------------------------
    reg [DATA_WIDTH-1:0] cur_word;          // word currently being transmitted
    reg [15:0]           xfer_len;          // number of words to transfer
    reg [15:0]           word_cnt;          // which word we are on
    reg [5:0]            bit_cnt;           // bit counter within word (0..31)
    reg                  captured_word;     // temporary capture of MISO (1‑bit)
    reg [DATA_WIDTH-1:0] rx_shift_reg;      // accumulates received word
    reg                  load_word;         // load next word from TX FIFO
    reg                  rx_fifo_wren_pulse;// pulse to write completed word

    // -----------------------------------------------------------------
    // Clock divider (generates SPI clock)
    // -----------------------------------------------------------------
    reg [1:0] sclk_div_cnt;
    wire      sclk_toggle;
    assign    sclk_toggle = (sclk_div_cnt == 2'b01);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) sclk_div_cnt <= 2'b00;
        else if (sclk_toggle) sclk_div_cnt <= 2'b00;
        else                 sclk_div_cnt <= sclk_div_cnt + 1'b1;
    end
    // spi_clk is high when divider counter is 0 (50 % duty)
    assign spi_clk = (sclk_div_cnt == 2'b00);

    // -----------------------------------------------------------------
    // APB interface control signals
    // -----------------------------------------------------------------
    wire write_enable = apb_psel && apb_penable && apb_pwrite;
    wire read_enable  = apb_psel && apb_penable && ~apb_pwrite;
    wire [7:0] addr     = apb_paddr;
    wire       wr_ctrl    = write_enable && (addr == ADDR_CTRL);
    wire       wr_intmask = write_enable && (addr == ADDR_INTMASK);
    wire       wr_status  = write_enable && (addr == ADDR_STATUS);
    wire       wr_tx_fifo = write_enable && (addr == ADDR_TXFIFO_WDATA);
    wire       wr_rx_fifo = write_enable && (addr == ADDR_RXFIFO_RDATA);
    wire       wr_dma_addr= write_enable && (addr == ADDR_DMA_ADDR);
    wire       wr_dma_len = write_enable && (addr == ADDR_DMA_LEN);
    wire       wr_dma_ctrl= write_enable && (addr == ADDR_DMA_CTRL);

    // APB read data mux
    reg [31:0] rdata_mux;
    always @* begin
        case (addr)
            ADDR_STATUS:      rdata_mux = reg_status;
            ADDR_RXFIFO_RDATA:rdata_mux = rx_fifo_dout;
            ADDR_DMA_ADDR:    rdata_mux = reg_dma_addr;
            ADDR_DMA_LEN:     rdata_mux = reg_dma_len;
            ADDR_DMA_CTRL:    rdata_mux = reg_dma_ctrl;
            default:          rdata_mux = 32'h0;
        endcase
    end
    assign apb_prdata = rdata_mux;
    assign apb_pready = apb_psel && apb_penable;   // simple ready
    assign apb_pslverr = (addr > ADDR_DMA_CTRL) || (addr < ADDR_CTRL);

    // -----------------------------------------------------------------
    // TX FIFO write side (external FIFO interface)
    // -----------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tx_wr_ptr <= 0;
            tx_rd_ptr <= 0;
            tx_fifo_full <= 0;
            tx_fifo_empty <= 1;
        end else begin
            if (tx_fifo_wen && !tx_fifo_full) begin
                tx_fifo_mem[tx_wr_ptr] <= tx_fifo_din;
                tx_wr_ptr <= tx_wr_ptr + 1'b1;
                tx_fifo_full <= (tx_wr_ptr == tx_rd_ptr + 1'b1);
                tx_fifo_empty <= 0;
            end
            if (tx_fifo_rden && !tx_fifo_empty) begin
                tx_fifo_dout <= tx_fifo_mem[tx_rd_ptr];
                tx_rd_ptr <= tx_rd_ptr + 1'b1;
                tx_fifo_empty <= (tx_rd_ptr == tx_wr_ptr);
                tx_fifo_full <= 0;
            end
        end
    end

    // -----------------------------------------------------------------
    // RX FIFO write side (shift engine writes completed words)
    // -----------------------------------------------------------------
