                tx_fifo_full <= 0;
            end
        end
    end

    // -----------------------------------------------------------------
    // RX FIFO write side (shift engine writes completed words)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_wr_ptr <= 0;
            rx_rd_ptr <= 0;
            rx_fifo_full <= 0;
            rx_fifo_empty <= 1;
        end else begin
            if (rx_fifo_wren && !rx_fifo_full) begin
                rx_fifo_mem[rx_wr_ptr] <= rx_shift_reg;
                rx_wr_ptr <= rx_wr_ptr + 1'b1;
                rx_fifo_full <= (rx_wr_ptr == rx_rd_ptr + 1'b1);
                rx_fifo_empty <= 0;
            end
            if (rx_fifo_wren_pulse && !rx_fifo_empty) begin
                rx_rd_ptr <= rx_rd_ptr + 1'b1;
                rx_fifo_empty <= (rx_rd_ptr == rx_wr_ptr);
                rx_fifo_full <= 0;
            end
        end
    end

    // -----------------------------------------------------------------
    // APB write to registers
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            reg_ctrl     <= 0;
            reg_intmask  <= 0;
            reg_dma_addr <= 0;
            reg_dma_len  <= 0;
            reg_dma_ctrl <= 0;
        end else begin
            if (wr_ctrl)      reg_ctrl     <= apb_pwdata;
            if (wr_intmask)   reg_intmask  <= apb_pwdata;
            if (wr_dma_addr)  reg_dma_addr <= apb_pwdata;
            if (wr_dma_len)   reg_dma_len  <= apb_pwdata;
            if (wr_dma_ctrl)  reg_dma_ctrl <= apb_pwdata;
        end
    end

    // -----------------------------------------------------------------
    // Start request generation (bit 0 of CTRL)
    // -----------------------------------------------------------------
    logic start_req;
    logic start_req_sync;
    logic start_req_edge;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            start_req     <= 0;
            start_req_sync<= 0;
            start_req_edge<= 0;
        end else begin
            start_req     <= reg_ctrl[0];
            start_req_sync<= start_req;
            start_req_edge<= start_req_sync && ~start_req;
        end
    end

    // -----------------------------------------------------------------
    // FSM state register
    // -----------------------------------------------------------------
    logic [2:0] fsm_state;
    logic [2:0] next_fsm_state;
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) fsm_state <= S_IDLE;
        else       fsm_state <= next_fsm_state;
    end

    // -----------------------------------------------------------------
    // Next‑state combinatorial logic
    // -----------------------------------------------------------------
    always_comb begin
        next_fsm_state = fsm_state;
        case (fsm_state)
            S_IDLE: begin
                if (start_req_edge) next_fsm_state = S_SETUP;
            end
            S_SETUP: begin
                // stay one cycle in setup
            end
            S_TX: begin
                if (bit_cnt == DATA_WIDTH-1) begin
                    if (word_cnt == xfer_len-1) next_fsm_state = S_WAIT;
                end
            end
            S_RX: begin
                if (bit_cnt == DATA_WIDTH-1) begin
                    if (word_cnt == xfer_len-1) next_fsm_state = S_WAIT;
                end
            end
            S_WAIT: begin
                next_fsm_state = S_DONE;
            end
            S_DONE: begin
                if (start_req_edge) next_fsm_state = S_SETUP;
                else               next_fsm_state = S_IDLE;
            end
            S_ERROR: begin
                next_fsm_state = S_IDLE;
            end
            default: next_fsm_state = S_IDLE;
        endcase
    end

    // -----------------------------------------------------------------
    // Shift engine sequential process
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_word      <= 0;
            xfer_len      <= 0;
            word_cnt      <= 0;
            bit_cnt       <= 0;
            captured_word <= 1'b0;
            load_word     <= 1'b0;
            rx_fifo_wren_pulse <= 1'b0;
            rx_shift_reg  <= 0;
        end else begin
            case (fsm_state)
                S_IDLE: begin
                    if (start_req_edge) begin
                        // Load transfer length and first word
                        xfer_len   <= reg_ctrl[15:0]; // example mapping
                        word_cnt   <= 0;
                        bit_cnt    <= 0;
                        cur_word   <= tx_fifo_mem[tx_rd_ptr];
                        load_word  <= 1'b1;
                    end
                end
                S_SETUP: begin
                    // hold setup for one cycle
                end
                S_TX: begin
                    // Drive MOSI with current bit (spi_mosi assignment elsewhere)
                    if (bit_cnt == DATA_WIDTH-1) begin
                        if (word_cnt == xfer_len-1) begin
                            // Transaction finished
                            load_word      <= 1'b0;
                            rx_fifo_wren_pulse <= 1'b1;
                        end else begin
                            // Prepare next word
                            word_cnt      <= word_cnt + 1'b1;
                            tx_fifo_rden  <= 1'b1;
                            cur_word      <= tx_fifo_mem[tx_rd_ptr];
                            load_word     <= 1'b1;
                        end
                    end else begin
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end
                S_RX: begin
                    // Capture MISO bit into captured_word
                    captured_word <= spi_miso;
                    // Build received word in rx_shift_reg
                    rx_shift_reg <= {rx_shift_reg[DATA_WIDTH-2:0], captured_word};
                    if (bit_cnt == DATA_WIDTH-1) begin
                        if (word_cnt == xfer_len-1) begin
                            load_word      <= 1'b0;
                            rx_fifo_wren_pulse <= 1'b1;
                        end else begin
                            word_cnt      <= word_cnt + 1'b1;
                            tx_fifo_rden  <= 1'b1;
                            cur_word      <= tx_fifo_mem[tx_rd_ptr];
                            load_word     <= 1'b1;
                        end
                    end else begin
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end
                S_WAIT: begin
                    // Hold wait for a couple of cycles
                end
                S_DONE: begin
                    // Pulse APB interrupt if enabled
                    if (start_req_edge) begin
                        // could set intr, etc.
                    end
                end
                S_ERROR: begin
                    // Handle error
                end
                default: begin
                    // Reset shift engine
                    cur_word      <= 0;
                    xfer_len      <= 0;
                    word_cnt      <= 0;
                    bit_cnt       <= 0;
                    load_word     <= 0;
                    rx_fifo_wren_pulse <= 0;
                end
            endcase

            // Pulse handling
            if (rx_fifo_wren_pulse && !rx_fifo_empty) begin
                rx_fifo_mem[rx_wr_ptr] <= rx_shift_reg;
                rx_wr_ptr <= rx_wr_ptr + 1'b1;
                rx_fifo_wren_pulse <= 1'b0;
            end
        end
    end

    // -----------------------------------------------------------------
    // Output assignments
    // -----------------------------------------------------------------
    assign spi_mosi = (fsm_state == S_TX) ? cur_word[bit_cnt] : 1'b0;
    assign spi_cs_n = (fsm_state != S_IDLE) ? 1'b0 : 1'b1;
    assign intr     = (fsm_state == S_DONE) && reg_intmask[0];
    assign dma_req  = (fsm_state == S_TX) && (word_cnt != 0);
    assign status   = reg_status[3:0]; // map 32‑bit status to 4‑bit output

    // -----------------------------------------------------------------
    // Status register update (example)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) reg_status <= 0;
        else begin
            if (rx_fifo_wren_pulse) reg_status[0] <= 1'b1; // set busy flag
            else if (fsm_state == S_IDLE) reg_status[0] <= 1'b0; // clear when idle
        end
    end

endmodule

module counter_8bit (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        enable,
    input  logic        load,
    input  logic        up_down,
    input  logic [7:0]  load_data,
    output logic [7:0]  count,
    output logic        overflow,
    output logic        underflow,
    output logic        zero_flag,
    output logic        max_flag
);

    // Internal registers
    logic [7:0] count_reg;
    logic [7:0] next_count;
    logic       overflow_reg;
    logic       underflow_reg;
    logic       zero_reg;
    logic       max_reg;

    // Combinational logic for next count value and flags
    always_comb begin
        next_count = count_reg;
        overflow_reg = 1'b0;
        underflow_reg = 1'b0;

        if (!rst_n) begin
            next_count = 8'h00;
        end else if (load) begin
            next_count = load_data;
        end else if (enable) begin
            if (up_down) begin
                {overflow_reg, next_count} = count_reg + 1;
            end else begin
                {underflow_reg, next_count} = count_reg - 1;
            end
        end
    end

    // Sequential logic for registers
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= 8'h00;
            overflow <= 1'b0;
            underflow <= 1'b0;
            zero_flag <= 1'b1;
            max_flag <= 1'b0;
        end else begin
            count_reg <= next_count;
            overflow <= overflow_reg;
            underflow <= underflow_reg;
            zero_flag <= (next_count == 8'h00);
            max_flag <= (next_count == 8'hFF);
        end
    end

    // Assign output
    assign count = count_reg;

endmodule

