// Transaction class
class Transaction;
    rand logic        enable;
    rand logic        load;
    rand logic        up_down;
    rand logic [7:0]  load_data;

    constraint c_valid { enable inside {0, 1}; load inside {0, 1}; up_down inside {0, 1}; }
endclass

// Driver class
class Driver;
    virtual counter_if vif;
    Transaction tr;

    function new(virtual counter_if vif);
        this.vif = vif;
    endfunction

    task drive();
        forever begin
            tr = new();
            assert(tr.randomize());

            @(posedge vif.clk);
            vif.enable    <= tr.enable;
            vif.load      <= tr.load;
            vif.up_down   <= tr.up_down;
            vif.load_data <= tr.load_data;
        end
    endtask
endclass

// Monitor class
class Monitor;
    virtual counter_if vif;
    mailbox#(Transaction) mbx;

    function new(virtual counter_if vif, mailbox#(Transaction) mbx);
        this.vif = vif;
        this.mbx = mbx;
    endfunction

    task monitor();
        Transaction tr;
        forever begin
            @(posedge vif.clk);
            #1; // Sample after propagation delay
            tr = new();
            tr.enable    = vif.enable;
            tr.load      = vif.load;
            tr.up_down   = vif.up_down;
            tr.load_data = vif.load_data;
            mbx.put(tr);
        end
    endtask
endclass

// Scoreboard class
class Scoreboard;
    mailbox#(Transaction) mbx;
    logic [7:0] expected_count;
    logic expected_zero_flag;
    logic expected_max_flag;
    int error_count;

    function new(mailbox#(Transaction) mbx);
        this.mbx = mbx;
        expected_count = 8'h00;
        expected_zero_flag = 1'b1;
        expected_max_flag = 1'b0;
        error_count = 0;
    endfunction

    task check(Transaction tr);
        logic [7:0] prev_count;
        prev_count = expected_count;

        // Apply reset condition
        if (!vif.rst_n) begin
            expected_count = 8'h00;
            expected_zero_flag = 1'b1;
            expected_max_flag = 1'b0;
            return;
        end

        // Apply functional behavior
        if (tr.load) begin
            expected_count = tr.load_data;
        end else if (tr.enable) begin
            if (tr.up_down) begin
                expected_count = expected_count + 1;
            end else begin
                expected_count = expected_count - 1;
            end
        end

        // Update flags
        expected_zero_flag = (expected_count == 8'h00);
        expected_max_flag = (expected_count == 8'hFF);

        // Check outputs after clock edge
        @(posedge vif.clk);
        #1; // Sample after propagation delay

        if (vif.count !== expected_count) begin
            $display("ERROR: Count mismatch. Expected: %0h, Got: %0h", expected_count, vif.count);
            error_count++;
        end

        if (vif.zero_flag !== expected_zero_flag) begin
            $display("ERROR: Zero flag mismatch. Expected: %b, Got: %b", expected_zero_flag, vif.zero_flag);
            error_count++;
        end

        if (vif.max_flag !== expected_max_flag) begin
            $display("ERROR: Max flag mismatch. Expected: %b, Got: %b", expected_max_flag, vif.max_flag);
            error_count++;
        end

        // Overflow/underflow are single-cycle pulses, harder to check reliably in this structure
        // They would require more sophisticated checking based on counting sequence
    endtask

    task run();
        Transaction tr;
        forever begin
            mbx.get(tr);
            check(tr);
        end
    endtask
endclass

