module demo_chip (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        en,
    output logic [7:0]  cnt,
    output logic        carry
);
    // -------------------------------------------------
    // Internal register declarations
    // -------------------------------------------------
    logic [7:0] cnt_reg;
    logic       carry_reg;

    // -------------------------------------------------
    // FSM state declaration
    // -------------------------------------------------
    typedef enum logic [1:0] {
        S_IDLE,
        S_INC
    } state_t;

    state_t state;
    state_t next_state;

    // -------------------------------------------------
    // Next‑state combinational logic
    // -------------------------------------------------
    always_comb begin
        // Default: hold current state
        next_state = state;

        // Asynchronous reset forces S_IDLE
        if (!rst_n) begin
            next_state = S_IDLE;
        end
        // When enabled, transition to increment state
        else if (en) begin
            next_state = S_INC;
        end
    end

    // -------------------------------------------------
    // State register (synchronous to clk, async reset)
    // -------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= S_IDLE;
            cnt_reg   <= 8'h00;
            carry_reg <= 1'b0;
        end else begin
            state <= next_state;

            // Increment path: compute carry before adding 1
            if (en) begin
                carry_reg <= (cnt_reg == 8'hFF);
                cnt_reg   <= cnt_reg + 1'b1;
            end
        end
    end

    // -------------------------------------------------
    // Output assignments
    // -------------------------------------------------
    assign cnt = cnt_reg;
    assign carry = carry_reg;

endmodule

module indi_drive_130 (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        clk_adc,

    input  logic        enable,
    input  logic [7:0]  speed_ref,
    input  logic        direction,
    input  logic        brake_en,
    output logic        fault_n,

    input  logic [2:0]  hall_sensors,
    input  logic [9:0]  current_sense,
