    logic [9:0]  over_current_limit;
    logic [9:0]  under_voltage_limit;
    logic [7:0]  over_temp_limit;

    // FSM state types
    typedef enum logic [3:0] {
        STATE_RESET      = 4'b0000,
        STATE_IDLE       = 4'b0001,
        STATE_STARTUP    = 4'b0010,
        STATE_RUN        = 4'b0011,
        STATE_ALIGN      = 4'b0100,
        STATE_COMMUTATE  = 4'b0101,
        STATE_BRAKE      = 4'b0110,
        STATE_FAULT      = 4'b0111,
        STATE_CALIBRATE  = 4'b1000
    } main_state_e;

    typedef enum logic [2:0] {
        COMM_STATE_1 = 3'b000,
        COMM_STATE_2 = 3'b001,
        COMM_STATE_3 = 3'b010,
        COMM_STATE_4 = 3'b011,
        COMM_STATE_5 = 3'b100,
        COMM_STATE_6 = 3'b101
    } comm_state_e;

    // State registers
    main_state_e state, next_state;

    // Hall sensor edge detection
    logic [2:0] hall_prev;
    logic [2:0] hall_edge;

    // Speed calculation
    logic [15:0] speed_counter;
    logic        speed_update;

    // Protection flags
    logic        over_current_fault;
    logic        under_voltage_fault;
    logic        over_temp_fault;
    logic        stall_detected;

    //-----------------------------------
    // Register assignments
    //-----------------------------------
    assign ctrl_enable     = config_data[7];
    assign ctrl_direction  = config_data[6];
    assign ctrl_brake_en   = config_data[5];
    assign ctrl_speed_ref  = config_data;
    assign pid_kp          = config_data;
    assign pid_ki          = config_data;
    assign pid_kd          = config_data;
    assign {dead_time_cfg, pwm_freq_sel} = config_data;

    assign status_data = (status_state == 4'h0) ? {status_fault, status_running, status_stall, status_state} :
                         (status_state == 4'h1) ? status_speed_fbk :
                         (status_state == 4'h2) ? status_current_fbk :
                         (status_state == 4'h3) ? status_voltage_fbk :
                                                  status_temp_fbk;

    //-----------------------------------
    // Sequential logic
    //-----------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_RESET;
            hall_prev <= 3'b000;
            integral_term <= 16'd0;
            comm_timer <= 16'd0;
            pwm_counter <= 16'd0;
            dead_time_counter <= 8'd0;
        end else begin
            state <= next_state;
            hall_prev <= hall_sensors;
            if (speed_update)
                integral_term <= integral_term + speed_error;
            comm_timer <= comm_timer + 1;
            pwm_counter <= pwm_counter + 1;
            if (dead_time_counter > 0)
                dead_time_counter <= dead_time_counter - 1;
        end
    end

    //-----------------------------------
    // Combinational logic
    //-----------------------------------
    always_comb begin
        next_state = state;

        case (state)
            STATE_RESET: begin
                if (rst_n)
                    next_state = STATE_IDLE;
            end

            STATE_IDLE: begin
                if (enable && !fault_n)
                    next_state = STATE_STARTUP;
            end

            STATE_STARTUP: begin
                next_state = STATE_ALIGN;
            end

            STATE_ALIGN: begin
                next_state = STATE_RUN;
            end

            STATE_RUN: begin
                if (brake_en || ctrl_brake_en)
                    next_state = STATE_BRAKE;
                else if (over_current_fault || under_voltage_fault || over_temp_fault || stall_detected)
                    next_state = STATE_FAULT;
                else if (comm_timer >= 16'd1000) // Example commutation period
                    next_state = STATE_COMMUTATE;
            end

            STATE_COMMUTATE: begin
                next_state = STATE_RUN;
            end

            STATE_BRAKE: begin
                if (!brake_en && !ctrl_brake_en)
                    next_state = STATE_IDLE;
            end

            STATE_FAULT: begin
                if (!(over_current_fault || under_voltage_fault || over_temp_fault))
                    next_state = STATE_IDLE;
            end

            STATE_CALIBRATE: begin
                next_state = STATE_IDLE;
            end
        endcase
    end

