    //-----------------------------------
    // PID controller
    //-----------------------------------
    always_comb begin
        speed_error = {8'd0, ctrl_speed_ref} - {8'd0, status_speed_fbk};
        derivative_term = speed_error - speed_error; // Simplified derivative
        pwm_duty_cycle = 8'(pid_kp * speed_error + pid_ki * integral_term + pid_kd * derivative_term);
    end

    //-----------------------------------
    // Commutation logic
