// Transaction class
class Transaction;
    rand logic        enable;
    rand logic [7:0]  speed_ref;
    rand logic        direction;
    rand logic        brake_en;
    rand logic [2:0]  hall_sensors;
    rand logic [9:0]  current_sense;
    rand logic [9:0]  bus_voltage;
    rand logic [7:0]  config_data;

    // SPI signals (not randomized in this simple test)
    logic             spi_clk;
    logic             spi_cs_n;
    logic             spi_mosi;

    constraint c_speed_ref { speed_ref inside {[0:200]}; }
    constraint c_current_sense { current_sense inside {[0:800]}; } // Below overcurrent limit
    constraint c_bus_voltage { bus_voltage inside {[250:1023]}; }  // Above undervoltage limit

    function void display(string name);
        $display("%s: enable=%b, speed_ref=%0d, direction=%b, brake_en=%b, hall_sensors=%b, current_sense=%0d, bus_voltage=%0d, config_data=0x%0h",
                 name, enable, speed_ref, direction, brake_en, hall_sensors, current_sense, bus_voltage, config_data);
    endfunction
endclass

// Driver class
class Driver;
    virtual indi_drive_130_if vif;
    Transaction tr;

    function new(virtual indi_drive_130_if vif);
        this.vif = vif;
    endfunction

    task drive(Transaction t);
        @(posedge vif.clk);
        vif.enable <= t.enable;
        vif.speed_ref <= t.speed_ref;
        vif.direction <= t.direction;
        vif.brake_en <= t.brake_en;
        vif.hall_sensors <= t.hall_sensors;
        vif.current_sense <= t.current_sense;
        vif.bus_voltage <= t.bus_voltage;
        vif.config_data <= t.config_data;

        // SPI signals (keeping them constant for simplicity)
        vif.spi_clk <= 0;
        vif.spi_cs_n <= 1;
        vif.spi_mosi <= 0;
    endtask

    task reset();
        vif.rst_n <= 0;
        repeat(10) @(posedge vif.clk);
        vif.rst_n <= 1;
    endtask
endclass

// Monitor class
class Monitor;
    virtual indi_drive_130_if vif;

    function new(virtual indi_drive_130_if vif);
