class Scoreboard;
    int error_count;

    function new();
        error_count = 0;
    endfunction

    function void check_fault(logic expected_fault_n, logic actual_fault_n);
        if (expected_fault_n !== actual_fault_n) begin
            $display("ERROR: Expected fault_n = %b, Got fault_n = %b", expected_fault_n, actual_fault_n);
            error_count++;
        end
    endfunction

    function void check_pwm(logic [2:0] expected_pwm_h, logic [2:0] expected_pwm_l,
                            logic [2:0] actual_pwm_h, logic [2:0] actual_pwm_l);
