module mini_tpu_4x4 (
    input  logic        clk,
    input  logic        rst_n,

    // Control signals
    input  logic        start,
    input  logic [1:0]  mode,
    input  logic        accumulate,
    output logic        done,

    // Data inputs
    input  logic [7:0]  weight_in_0,
    input  logic [7:0]  weight_in_1,
    input  logic [7:0]  weight_in_2,
    input  logic [7:0]  weight_in_3,

    input  logic [7:0]  activation_in_0,
    input  logic [7:0]  activation_in_1,
    input  logic [7:0]  activation_in_2,
    input  logic [7:0]  activation_in_3,

    // Data outputs
    output logic [23:0] psum_out_0,
    output logic [23:0] psum_out_1,
    output logic [23:0] psum_out_2,
    output logic [23:0] psum_out_3,

    output logic [7:0]  weight_out_0,
    output logic [7:0]  weight_out_1,
    output logic [7:0]  weight_out_2,
    output logic [7:0]  weight_out_3,

    // Configuration interface
    input  logic [31:0] config_addr,
    input  logic [31:0] config_wdata,
    input  logic        config_write,
    output logic [31:0] config_rdata,
    output logic        config_ready
);

    // State types
    typedef enum logic [2:0] {
        IDLE_STATE      = 3'b000,
        CONFIG_STATE    = 3'b001,
        COMPUTE_STATE   = 3'b010,
        ACCUMULATE_STATE = 3'b011,
        OUTPUT_STATE    = 3'b100,
        DONE_STATE      = 3'b101,
        ERROR_STATE     = 3'b110
    } tpu_state_e;

    typedef enum logic [1:0] {
        PE_IDLE_STATE    = 2'b00,
        PE_COMPUTE_STATE = 2'b01,
        PE_FORWARD_STATE = 2'b10,
        PE_DONE_STATE    = 2'b11
    } pe_state_e;

    // Internal registers
    tpu_state_e state, next_state;

    // Configuration registers
    logic [31:0] ctrl_reg;
    logic [31:0] status_reg;
    logic [31:0] iteration_count_reg;
    logic [31:0] config_reg;

    // Done signal
    logic done_internal;

    // PE array signals
    logic [7:0]  pe_weight_in [0:3][0:3];
    logic [7:0]  pe_activation_in [0:3][0:3];
    logic [23:0] pe_psum_out [0:3][0:3];
    logic [7:0]  pe_weight_out [0:3][0:3];
    logic        pe_valid [0:3][0:3];
    logic        pe_last [0:3][0:3];
    pe_state_e   pe_state [0:3][0:3];
    pe_state_e   pe_next_state [0:3][0:3];

    // PE internal registers
    logic [7:0]  weight_reg [0:3][0:3];
    logic [7:0]  activation_reg [0:3][0:3];
    logic [23:0] accumulator_reg [0:3][0:3];
    logic [23:0] psum_reg [0:3][0:3];
    logic        valid_reg [0:3][0:3];
    logic        last_reg [0:3][0:3];

    // Assign inputs to first column/row of PE array
    always_comb begin
        // First column (weights flow vertically)
        pe_weight_in[0][0] = weight_in_0;
        pe_weight_in[1][0] = weight_in_1;
        pe_weight_in[2][0] = weight_in_2;
        pe_weight_in[3][0] = weight_in_3;

        // First row (activations flow horizontally)
        pe_activation_in[0][0] = activation_in_0;
        pe_activation_in[0][1] = activation_in_1;
        pe_activation_in[0][2] = activation_in_2;
        pe_activation_in[0][3] = activation_in_3;

        // Connect PEs internally
        for (int i = 0; i < 4; i++) begin
            for (int j = 0; j < 4; j++) begin
                if (i > 0) 
                    pe_weight_in[i][j] = pe_weight_out[i-1][j];
                if (j > 0) 
                    pe_activation_in[i][j] = pe_activation_in[i][j-1];
            end
        end

        // Outputs
        psum_out_0 = pe_psum_out[3][0];
        psum_out_1 = pe_psum_out[3][1];
        psum_out_2 = pe_psum_out[3][2];
        psum_out_3 = pe_psum_out[3][3];

        weight_out_0 = pe_weight_out[3][0];
        weight_out_1 = pe_weight_out[3][1];
        weight_out_2 = pe_weight_out[3][2];
        weight_out_3 = pe_weight_out[3][3];
    end

    // Main FSM sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE_STATE;
            ctrl_reg <= 32'h0;
            status_reg <= 32'h0;
            iteration_count_reg <= 32'h0;
            config_reg <= 32'h0;
        end else begin
            state <= next_state;

            // Configuration writes
            if (config_write) begin
                case (config_addr)
                    32'h00: ctrl_reg <= config_wdata;
                    32'h08: iteration_count_reg <= config_wdata;
                    32'h0C: config_reg <= config_wdata;
                    default: ;
                endcase
            end

            // Clear done when starting new operation
            if (start)
                status_reg[1] <= 1'b0;

            // Set done when operation completes
            if (done_internal)
                status_reg[1] <= 1'b1;
        end
    end

    // Main FSM combinational logic
    always_comb begin
        next_state = state;
        done_internal = 1'b0;
        config_rdata = 32'h0;
        config_ready = 1'b1;

        case (state)
            IDLE_STATE: begin
                if (start)
                    next_state = CONFIG_STATE;
            end

            CONFIG_STATE: begin
                next_state = COMPUTE_STATE;
            end

            COMPUTE_STATE: begin
                next_state = ACCUMULATE_STATE;
            end

            ACCUMULATE_STATE: begin
                next_state = OUTPUT_STATE;
            end

            OUTPUT_STATE: begin
                next_state = DONE_STATE;
            end

            DONE_STATE: begin
                done_internal = 1'b1;
                next_state = IDLE_STATE;
            end

            ERROR_STATE: begin
                next_state = IDLE_STATE;
            end

            default: begin
                next_state = IDLE_STATE;
            end
        endcase

        // Read configuration registers
        case (config_addr)
            32'h00: config_rdata = ctrl_reg;
            32'h04: config_rdata = status_reg;
            32'h08: config_rdata = iteration_count_reg;
            32'h0C: config_rdata = config_reg;
            default: config_rdata = 32'h0;
        endcase
    end

    // Assign output
    assign done = status_reg[1];

    // PE Array Implementation
    genvar i, j;
    generate
        for (i = 0; i < 4; i++) begin : gen_rows
            for (j = 0; j < 4; j++) begin : gen_cols
                // PE FSM sequential logic
                always_ff @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        pe_state[i][j] <= PE_IDLE_STATE;
                        weight_reg[i][j] <= 8'h0;
                        activation_reg[i][j] <= 8'h0;
                        accumulator_reg[i][j] <= 24'h0;
                        psum_reg[i][j] <= 24'h0;
                        valid_reg[i][j] <= 1'b0;
                        last_reg[i][j] <= 1'b0;
                    end else begin
                        pe_state[i][j] <= pe_next_state[i][j];

                        case (pe_next_state[i][j])
                            PE_COMPUTE_STATE: begin
                                weight_reg[i][j] <= pe_weight_in[i][j];
                                activation_reg[i][j] <= pe_activation_in[i][j];
                                valid_reg[i][j] <= 1'b1;

                                // Perform MAC operation
                                if (accumulate && valid_reg[i][j]) begin
                                    accumulator_reg[i][j] <= accumulator_reg[i][j] + ($signed(weight_reg[i][j]) * $signed(activation_reg[i][j]));
                                end else begin
                                    accumulator_reg[i][j] <= $signed(weight_reg[i][j]) * $signed(activation_reg[i][j]);
                                end
                            end

                            PE_FORWARD_STATE: begin
                                psum_reg[i][j] <= accumulator_reg[i][j];
                            end

                            default: ;
                        endcase
                    end
                end

                // PE FSM combinational logic
                always_comb begin
                    pe_next_state[i][j] = pe_state[i][j];
                    pe_weight_out[i][j] = pe_weight_in[i][j];
                    pe_activation_in[i][j] = 8'h0; // Will be overridden by connections
                    pe_psum_out[i][j] = psum_reg[i][j];

                    case (pe_state[i][j])
                        PE_IDLE_STATE: begin
                            if (pe_weight_in[i][j] != 0 || pe_activation_in[i][j] != 0)
                                pe_next_state[i][j] = PE_COMPUTE_STATE;
                        end

                        PE_COMPUTE_STATE: begin
                            pe_next_state[i][j] = PE_FORWARD_STATE;
                        end

                        PE_FORWARD_STATE: begin
                            pe_next_state[i][j] = PE_DONE_STATE;
                        end

                        PE_DONE_STATE: begin
                            pe_next_state[i][j] = PE_IDLE_STATE;
                        end

                        default: begin
                            pe_next_state[i][j] = PE_IDLE_STATE;
                        end
                    endcase
                end
            end
        end
    endgenerate

endmodule

