interface my_chip_if;
  logic clk;
  logic rst_n;
  logic en;
  logic [7:0] cnt;
  logic cnt_ld;
  modport drv (input clk, output rst_n, en);
  modport mon (input clk, cnt, cnt_ld);
endinterface

class Transaction;
  rand bit [31:0] stimulus;
  bit has_x;
endclass

class Driver;
  virtual my_chip_if vif;
  function new(virtual my_chip_if vif);
    this.vif = vif;
  endfunction

  task reset_phase();
    vif.rst_n = 1'b0;
    repeat (5) @(posedge vif.clk);
    vif.rst_n = 1'b1;
  endtask

  task drive_step();
    @(posedge vif.clk);
    vif.en = $urandom_range(0, 1);
  endtask
endclass

class Monitor;
  virtual my_chip_if vif;
  function new(virtual my_chip_if vif);
    this.vif = vif;
  endfunction
  function bit has_unknown_output();
    bit bad;
    bad = 0;
    if (^(vif.cnt) === 1'bx) bad = 1;
    if (^(vif.cnt_ld) === 1'bx) bad = 1;
    return bad;
  endfunction
endclass

class Scoreboard;
  int errors;
  function new();
    errors = 0;
  endfunction
  function void sample(bit has_x);
    if (has_x) begin
      $display("TEST FAILED: X/Z detected on DUT output.");
      errors++;
    end
  endfunction
endclass

class Environment;
  virtual my_chip_if vif;
  Driver drv;
  Monitor mon;
  Scoreboard sb;
  function new(virtual my_chip_if vif);
    this.vif = vif;
    drv = new(vif);
    mon = new(vif);
    sb = new();
  endfunction
  task run();
    drv.reset_phase();
    repeat (40) begin
      drv.drive_step();
      sb.sample(mon.has_unknown_output());
    end
    if (sb.errors == 0) begin
      $display("TEST PASSED");
    end else begin
      $display("TEST FAILED");
    end
  endtask
endclass

module my_chip_tb;
  my_chip_if vif();

  my_chip dut (
    .clk(vif.clk),
    .rst_n(vif.rst_n),
    .en(vif.en),
    .cnt(vif.cnt),
    .cnt_ld(vif.cnt_ld)
  );

  initial begin
    vif.clk = 1'b0;
    forever #5 vif.clk = ~vif.clk;
  end

  initial begin
    Environment env;
    env = new(vif);
    env.run();
    $finish;
  end
endmodule

