            BOOT_RESET: boot_next_state = BOOT_INIT;
            BOOT_INIT: boot_next_state = BOOT_LOAD;
            BOOT_LOAD: boot_next_state = BOOT_HASH;
            BOOT_HASH: boot_next_state = BOOT_COMPARE;
