module small_fifo (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       push,
    input  logic       pop,
    input  logic [7:0] data_in,
    output logic [7:0] data_out,
    output logic       full,
    output logic       empty
);

    // Parameters
    localparam DEPTH = 4;
    localparam PTR_WIDTH = 2;
    localparam COUNT_WIDTH = 3;

    // State type definition
    typedef enum logic [1:0] {
        IDLE        = 2'b00,
        PUSH        = 2'b01,
        POP         = 2'b10,
        PUSHTHROUGH = 2'b11
    } fifo_state_t;

    // Memory array
    logic [7:0] fifo_mem [0:3];

    // Registered signals
    logic [PTR_WIDTH-1:0]  wr_ptr;
    logic [PTR_WIDTH-1:0]  rd_ptr;
    logic [COUNT_WIDTH-1:0] count;
    logic                  full_flag;
    logic                  empty_flag;
    fifo_state_t           state;
    logic [7:0]            data_out_reg;

    // Combinational signals
    logic [PTR_WIDTH-1:0]  next_wr_ptr;
    logic [PTR_WIDTH-1:0]  next_rd_ptr;
    logic [COUNT_WIDTH-1:0] next_count;
    logic                  wr_en;
    logic                  rd_en;
    fifo_state_t           next_state;
    logic                  full_comb;
    logic                  empty_comb;

    // FSM state transition
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Sequential elements
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            count  <= '0;
        end else begin
            wr_ptr <= next_wr_ptr;
            rd_ptr <= next_rd_ptr;
            count  <= next_count;
        end
    end

    // Memory write
    always_ff @(posedge clk) begin
        if (wr_en) begin
            fifo_mem[wr_ptr] <= data_in;
        end
    end

    // Output registers
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out_reg <= '0;
            full_flag    <= 1'b0;
            empty_flag   <= 1'b1;
        end else begin
            data_out_reg <= fifo_mem[rd_ptr];
            full_flag    <= full_comb;
            empty_flag   <= empty_comb;
        end
    end

    // Combinational logic for next state
    always_comb begin
        case (state)
            IDLE: begin
                if (push && !pop && !full_comb) 
                    next_state = PUSH;
                else if (!push && pop && !empty_comb) 
                    next_state = POP;
                else if (push && pop) begin
                    if (empty_comb)
                        next_state = PUSH;
                    else if (full_comb)
                        next_state = POP;
                    else
                        next_state = PUSHTHROUGH;
                end else
                    next_state = IDLE;
            end
            PUSH: begin
                if (push && !pop && !full_comb)
                    next_state = PUSH;
                else if (!push && pop && !empty_comb)
                    next_state = POP;
                else if (push && pop) begin
                    if (empty_comb)
                        next_state = PUSH;
                    else if (full_comb)
                        next_state = POP;
                    else
                        next_state = PUSHTHROUGH;
                end else
                    next_state = IDLE;
            end
            POP: begin
                if (push && !pop && !full_comb)
                    next_state = PUSH;
                else if (!push && pop && !empty_comb)
                    next_state = POP;
                else if (push && pop) begin
                    if (empty_comb)
                        next_state = PUSH;
                    else if (full_comb)
                        next_state = POP;
                    else
                        next_state = PUSHTHROUGH;
                end else
                    next_state = IDLE;
            end
            PUSHTHROUGH: begin
                if (push && !pop && !full_comb)
                    next_state = PUSH;
                else if (!push && pop && !empty_comb)
                    next_state = POP;
                else if (push && pop && !empty_comb && !full_comb)
                    next_state = PUSHTHROUGH;
                else
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Control signal generation
    always_comb begin
        wr_en = 1'b0;
        rd_en = 1'b0;

        case (next_state)
            PUSH: begin
                wr_en = 1'b1;
                rd_en = 1'b0;
            end
            POP: begin
                wr_en = 1'b0;
                rd_en = 1'b1;
            end
            PUSHTHROUGH: begin
                wr_en = 1'b1;
                rd_en = 1'b1;
            end
            default: begin
                wr_en = 1'b0;
                rd_en = 1'b0;
            end
        endcase
    end

    // Pointer and count calculations
    always_comb begin
        next_wr_ptr = wr_ptr;
        next_rd_ptr = rd_ptr;
        next_count  = count;

        case (next_state)
            PUSH: begin
                next_wr_ptr = wr_ptr + 1'b1;
                next_count  = count + 1'b1;
            end
            POP: begin
                next_rd_ptr = rd_ptr + 1'b1;
                next_count  = count - 1'b1;
            end
            PUSHTHROUGH: begin
                next_wr_ptr = wr_ptr + 1'b1;
                next_rd_ptr = rd_ptr + 1'b1;
                // count remains unchanged
            end
            default: begin
                // No change to pointers or count
            end
        endcase
    end

    // Flag generation logic
    always_comb begin
        full_comb  = (count == DEPTH);
        empty_comb = (count == 0);
    end

    // Assign outputs
    assign data_out = data_out_reg;
    assign full     = full_flag;
    assign empty    = empty_flag;

endmodule

