                    next_state = IDLE;
            end
            PUSHTHROUGH: begin
                if (push && !pop && !full_comb)
                    next_state = PUSH;
                else if (!push && pop && !empty_comb)
                    next_state = POP;
                else if (push && pop && !empty_comb && !full_comb)
                    next_state = PUSHTHROUGH;
                else
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Control signal generation
    always_comb begin
        wr_en = 1'b0;
        rd_en = 1'b0;

        case (next_state)
            PUSH: begin
                wr_en = 1'b1;
                rd_en = 1'b0;
            end
            POP: begin
                wr_en = 1'b0;
                rd_en = 1'b1;
            end
            PUSHTHROUGH: begin
                wr_en = 1'b1;
                rd_en = 1'b1;
            end
            default: begin
                wr_en = 1'b0;
                rd_en = 1'b0;
            end
        endcase
    end

    // Pointer and count calculations
    always_comb begin
        next_wr_ptr = wr_ptr;
        next_rd_ptr = rd_ptr;
        next_count  = count;

        case (next_state)
            PUSH: begin
                next_wr_ptr = wr_ptr + 1'b1;
                next_count  = count + 1'b1;
            end
            POP: begin
                next_rd_ptr = rd_ptr + 1'b1;
                next_count  = count - 1'b1;
            end
            PUSHTHROUGH: begin
                next_wr_ptr = wr_ptr + 1'b1;
                next_rd_ptr = rd_ptr + 1'b1;
                // count remains unchanged
            end
            default: begin
                // No change to pointers or count
            end
        endcase
    end

    // Flag generation logic
    always_comb begin
        full_comb  = (count == DEPTH);
        empty_comb = (count == 0);
    end

    // Assign outputs
    assign data_out = data_out_reg;
    assign full     = full_flag;
    assign empty    = empty_flag;

endmodule
