module test_orch_log_v1 (
    input clk,
    input rst_n,
    output [3:0] count
);

localparam RESET = 1'b0;
localparam COUNT = 1'b1;

reg [3:0] count_reg;
reg state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count_reg <= 4'b0;
        state <= RESET;
    end else begin
        case (state)
            RESET: begin
                count_reg <= 4'b0;
                state <= COUNT;
            end
            COUNT: begin
                count_reg <= count_reg + 1;
                state <= COUNT;
            end
            default: begin
                count_reg <= 4'b0;
                state <= RESET;
            end
        endcase
    end
end

assign count = count_reg;

endmodule

