    typedef enum logic [3:0] {
        OP_NOP  = 4'h0,
        OP_ADD  = 4'h1,
        OP_SUB  = 4'h2,
        OP_AND  = 4'h3,
        OP_OR   = 4'h4,
        OP_XOR  = 4'h5,
        OP_SLL  = 4'h6,
        OP_SRL  = 4'h7,
        OP_SRA  = 4'h8,
        OP_LW   = 4'h9,
        OP_SW   = 4'ha,
        OP_BEQ  = 4'hb,
        OP_BNE  = 4'hc,
        OP_JAL  = 4'hd
    } opcode_t;

    // ------------------------------------------------------------
    //  Pipeline Register (Decode -> Execute)
    // ------------------------------------------------------------
    typedef struct packed {
        logic [ADDR_WIDTH-1:0] pc;
        logic [DATA_WIDTH-1:0] instr;
        opcode_t               opcode;
        logic [2:0]            rd;
        logic [2:0]            rs1;
        logic [2:0]            rs2;
        logic [DATA_WIDTH-1:0] imm;
    } pipeline_t;

    // ------------------------------------------------------------
    //  Register File (Triple‑ported)
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] rf_a [REG_COUNT];
    logic [DATA_WIDTH-1:0] rf_b [REG_COUNT];
    logic [DATA_WIDTH-1:0] rf_c [REG_COUNT];

    // ------------------------------------------------------------
    //  PC Registers (Triple‑copied)
    // ------------------------------------------------------------
    logic [ADDR_WIDTH-1:0] pc_a, pc_b, pc_c;
    logic [ADDR_WIDTH-1:0] pc_next;          // next PC value to be fetched

    // ------------------------------------------------------------
    //  FSM State Declaration
    // ------------------------------------------------------------
    typedef enum logic [2:0] {
        S_IDLE        = 3'd0,
        S_IFETCH      = 3'd1,
        S_DECODE      = 3'd2,
        S_EXECUTE     = 3'd3,
        S_EXECUTE_WAIT= 3'd4,
        S_WRITEBACK   = 3'd5,
        S_EXCEPTION   = 3'd6
    } state_t;

    state_t state, next_state;

    // ------------------------------------------------------------
    //  Pipeline Register (latched in Decode stage)
    // ------------------------------------------------------------
    pipeline_t pipe_reg;

    // ------------------------------------------------------------
    //  Instruction Memory (ROM)
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] instr_mem [INSTR_MEM_SIZE];

    // ------------------------------------------------------------
    //  Data Memory (RAM)
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] data_mem [INSTR_MEM_SIZE];

    // ------------------------------------------------------------
    //  Fetched Instruction Register
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] ir_fetch;

    // ------------------------------------------------------------
    //  Decoded Fields (latched in Decode stage)
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] imm_fetch;
    logic [2:0]            rd_fetch;
    logic [2:0]            rs1_fetch;
    logic [2:0]            rs2_fetch;
    opcode_t               opcode_fetch;

    // ------------------------------------------------------------
    //  Operand Triplets (read in Execute stage)
    // ------------------------------------------------------------
    // (removed – operands are taken directly from rf_* arrays)

    // ------------------------------------------------------------
    //  ALU Result Triplets
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] alu_res_a, alu_res_b, alu_res_c;
    logic                  alu_ok;
    logic                  tmr_err;

    // ------------------------------------------------------------
    //  Status Flags (triple‑copied)
    // ------------------------------------------------------------
    logic [2:0] flags_z_a, flags_z_b, flags_z_c;
    logic [2:0] flags_n_a, flags_n_b, flags_n_c;
    logic [2:0] flags_c_a, flags_c_b, flags_c_c;
    logic [2:0] flags_v_a, flags_v_b, flags_v_c;
    logic       zero_err, neg_err, carry_err, overflow_err;

    // ------------------------------------------------------------
    //  Timer Counter (generates timer_int)
    // ------------------------------------------------------------
    logic [7:0] timer_cnt;
    logic       timer_int_int;

    // ------------------------------------------------------------
    //  FSM Combinatorial Next‑State Logic
    // ------------------------------------------------------------
    always_comb begin
        next_state = state;
        case (state)
            S_IDLE:      if (!rst_n)               next_state = S_IDLE;
            S_IFETCH:    if (ir_fetch !== 'x)      next_state = S_DECODE;
            S_DECODE:    if (ir_fetch !== 'x)      next_state = S_EXECUTE;
            S_EXECUTE:   next_state = S_EXECUTE_WAIT;
            S_EXECUTE_WAIT: 
                               if (alu_ok)               next_state = S_WRITEBACK;
                               else                       next_state = S_EXCEPTION;
            S_WRITEBACK:  next_state = S_IFETCH;
            S_EXCEPTION:  next_state = S_IFETCH;
            default:      next_state = S_IDLE;
        endcase
    end

    // ------------------------------------------------------------
    //  State Register (positive‑edge, async active‑low reset)
    // ------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    // ------------------------------------------------------------
    //  Fetch Stage (S_IFETCH)
    // ------------------------------------------------------------
    assign addr = pc_next;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ir_fetch <= '0;
        end else if (state == S_IFETCH && clk_en) begin
            ir_fetch <= instr_mem[pc_next];
        end
    end

    // Decode fetched instruction
    always_comb begin
        opcode_fetch = opcode_t'(ir_fetch[31:28]); // explicit cast
        rd_fetch     = ir_fetch[27:25];
        rs1_fetch    = ir_fetch[24:22];
        rs2_fetch    = ir_fetch[21:19];
        // Sign‑extend 12‑bit immediate (fixed width)
        imm_fetch    = {{20{ir_fetch[31]}}, ir_fetch[31:20]};
    end

    // ------------------------------------------------------------
    //  Register File Read (triple‑ported) – performed in Decode stage
    // ------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // No read on reset
        end else if (state == S_DECODE && clk_en) begin
            // Values are latched for later use
        end
    end

    // ------------------------------------------------------------
    //  Pipeline Register Latch (end of Decode -> Execute)
    // ------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_reg <= '0;
        end else if (state == S_DECODE && clk_en) begin
            pipe_reg.pc      <= pc_next;
            pipe_reg.instr   <= ir_fetch;
            pipe_reg.opcode  <= opcode_fetch;
            pipe_reg.rd      <= rd_fetch;
            pipe_reg.rs1     <= rs1_fetch;
            pipe_reg.rs2     <= rs2_fetch;
            pipe_reg.imm     <= imm_fetch;
        end
    end

    // ------------------------------------------------------------
    //  Execute Stage – TMR ALU (three identical functional units)
    // ------------------------------------------------------------
    always_comb begin
        // Temporary results for each of the three functional units
        logic [DATA_WIDTH-1:0] temp_a;
        logic [DATA_WIDTH-1:0] temp_b;
        logic [DATA_WIDTH-1:0] temp_c;

        // Default result
        temp_a = 32'h0;
        temp_b = 32'h0;
        temp_c = 32'h0;

        case (pipe_reg.opcode)
            OP_ADD: begin
                temp_a = rf_a[pipe_reg.rs1] + rf_a[pipe_reg.rs2] + pipe_reg.imm;
                temp_b = rf_b[pipe_reg.rs1] + rf_b[pipe_reg.rs2] + pipe_reg.imm;
                temp_c = rf_c[pipe_reg.rs1] + rf_c[pipe_reg.rs2] + pipe_reg.imm;
            end
            OP_SUB: begin
                temp_a = rf_a[pipe_reg.rs1] - rf_a[pipe_reg.rs2] - pipe_reg.imm;
                temp_b = rf_b[pipe_reg.rs1] - rf_b[pipe_reg.rs2] - pipe_reg.imm;
                temp_c = rf_c[pipe_reg.rs1] - rf_c[pipe_reg.rs2] - pipe_reg.imm;
            end
            OP_AND: begin
                temp_a = rf_a[pipe_reg.rs1] & rf_a[pipe_reg.rs2];
                temp_b = rf_b[pipe_reg.rs1] & rf_b[pipe_reg.rs2];
                temp_c = rf_c[pipe_reg.rs1] & rf_c[pipe_reg.rs2];
            end
            OP_OR : begin
                temp_a = rf_a[pipe_reg.rs1] | rf_a[pipe_reg.rs2];
                temp_b = rf_b[pipe_reg.rs1] | rf_b[pipe_reg.rs2];
                temp_c = rf_c[pipe_reg.rs1] | rf_c[pipe_reg.rs2];
            end
            OP_XOR: begin
                temp_a = rf_a[pipe_reg.rs1] ^ rf_a[pipe_reg.rs2];
                temp_b = rf_b[pipe_reg.rs1] ^ rf_b[pipe_reg.rs2];
                temp_c = rf_c[pipe_reg.rs1] ^ rf_c[pipe_reg.rs2];
            end
            OP_SLL: begin
                temp_a = rf_a[pipe_reg.rs1] << rf_a[pipe_reg.rs2][4:0];
                temp_b = rf_b[pipe_reg.rs1] << rf_b[pipe_reg.rs2][4:0];
                temp_c = rf_c[pipe_reg.rs1] << rf_c[pipe_reg.rs2][4:0];
            end
            OP_SRL: begin
                temp_a = rf_a[pipe_reg.rs1] >> rf_a[pipe_reg.rs2][4:0];
                temp_b = rf_b[pipe_reg.rs1] >> rf_b[pipe_reg.rs2][4:0];
                temp_c = rf_c[pipe_reg.rs1] >> rf_c[pipe_reg.rs2][4:0];
            end
            OP_SRA: begin
                temp_a = $signed(rf_a[pipe_reg.rs1]) >>> rf_a[pipe_reg.rs2][4:0];
                temp_b = $signed(rf_b[pipe_reg.rs1]) >>> rf_b[pipe_reg.rs2][4:0];
                temp_c = $signed(rf_c[pipe_reg.rs1]) >>> rf_c[pipe_reg.rs2][4:0];
            end
            OP_LW : begin
                temp_a = rf_a[pipe_reg.rs1] + rf_a[pipe_reg.rs2];
                temp_b = rf_b[pipe_reg.rs1] + rf_b[pipe_reg.rs2];
                temp_c = rf_c[pipe_reg.rs1] + rf_c[pipe_reg.rs2];
            end
            OP_SW : begin
                temp_a = rf_a[pipe_reg.rs1] + rf_a[pipe_reg.rs2];
                temp_b = rf_b[pipe_reg.rs1] + rf_b[pipe_reg.rs2];
                temp_c = rf_c[pipe_reg.rs1] + rf_c[pipe_reg.rs2];
            end
            OP_BEQ, OP_BNE: begin
                temp_a = (rf_a[pipe_reg.rs1] == rf_a[pipe_reg.rs2]) ? 32'h1 : 32'h0;
                temp_b = (rf_b[pipe_reg.rs1] == rf_b[pipe_reg.rs2]) ? 32'h1 : 32'h0;
                temp_c = (rf_c[pipe_reg.rs1] == rf_c[pipe_reg.rs2]) ? 32'h1 : 32'h0;
            end
            OP_JAL: begin
                temp_a = {16'h0, pipe_reg.pc} + 4;
                temp_b = {16'h0, pipe_reg.pc} + 4;
                temp_c = {16'h0, pipe_reg.pc} + 4;
            end
            default: begin
                temp_a = 32'h0;
                temp_b = 32'h0;
                temp_c = 32'h0;
            end
        endcase

        // Majority voting
        logic [31:0] maj_res;
        for (int i = 0; i < DATA_WIDTH; i = i + 1) begin
            maj_res[i] = ( (temp_a[i] & temp_b[i]) |
                         (temp_a[i] & temp_c[i]) |
                         (temp_b[i] & temp_c[i]) );
        end

        // Drive final result
        alu_res_a = maj_res;
        alu_res_b = maj_res;
        alu_res_c = maj_res;

        // ALU OK and error flag
        alu_ok = (alu_res_a == alu_res_b) && (alu_res_b == alu_res_c);
        tmr_err = ~alu_ok;
    end

    // ------------------------------------------------------------
    //  Status Flags Generation (triple‑copied)
    // ------------------------------------------------------------
    // Zero flag
    always_comb begin
        flags_z_a[0] = (alu_res_a == 32'h0);
        flags_z_b[0] = (alu_res_b == 32'h0);
        flags_z_c[0] = (alu_res_c == 32'h0);
    end
    // Negative flag
    always_comb begin
        flags_n_a[0] = alu_res_a[31];
        flags_n_b[0] = alu_res_b[31];
        flags_n_c[0] = alu_res_c[31];
    end
    // Carry flag – simplified to zero to avoid undefined references
    always_comb begin
        flags_c_a[0] = 1'b0;
        flags_c_b[0] = 1'b0;
        flags_c_c[0] = 1'b0;
    end
    // Overflow flag – simplified to zero
    always_comb begin
        flags_v_a[0] = 1'b0;
        flags_v_b[0] = 1'b0;
        flags_v_c[0] = 1'b0;
    end

    // Majority voting for each flag vector
    always_comb begin
        zero_err   = (flags_z_a[1] & flags_z_b[1]) |
                    (flags_z_a[1] & flags_z_c[1]) |
                    (flags_z_b[1] & flags_z_c[1]);
        neg_err    = (flags_n_a[1] & flags_n_b[1]) |
                    (flags_n_a[1] & flags_n_c[1]) |
                    (flags_n_b[1] & flags_n_c[1]);
        carry_err  = (flags_c_a[1] & flags_c_b[1]) |
                    (flags_c_a[1] & flags_c_c[1]) |
                    (flags_c_b[1] & flags_c_c[1]);
        overflow_err = (flags_v_a[1] & flags_v_b[1]) |
                      (flags_v_a[1] & flags_v_c[1]) |
                      (flags_v_b[1] & flags_v_c[1]);
    end

    // ------------------------------------------------------------
    //  Write‑Back Stage (S_WRITEBACK)
    // ------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // No write on reset
        end else if (state == S_WRITEBACK && clk_en) begin
            // Write back to RF
            rf_a[pipe_reg.rd] <= alu_res_a;
            rf_b[pipe_reg.rd] <= alu_res_a;
            rf_c[pipe_reg.rd] <= alu_res_a;

            // Write back PC (for JAL/Branch)
            pc_a <= pc_next;
            pc_b <= pc_next;
            pc_c <= pc_next;
        end
    end

    // ------------------------------------------------------------
    //  PC Next‑Fetch Address Logic (combines all cases)
    // ------------------------------------------------------------
    always_comb begin
        if (state == S_EXCEPTION) begin
            pc_next = 16'h0010;
        end else begin
            // Default: sequential increment
            pc_next = pc_a + 4;

            case (pipe_reg.opcode)
                OP_BEQ, OP_BNE: begin
                    logic [15:0] imm_se;
                    imm_se = { {4{pipe_reg.imm[11]}}, pipe_reg.imm[11:0] };
                    pc_next = pc_a + (imm_se << 2);
                end
                OP_JAL: begin
                    logic [15:0] imm_se;
                    imm_se = { {4{pipe_reg.imm[11]}}, pipe_reg.imm[11:0] };
                    pc_next = imm_se << 2;
                end
                default: pc_next = pc_a + 4;
            endcase
        end
    end

    // ------------------------------------------------------------
    //  Exception / Interrupt Handling (S_EXCEPTION)
    // ------------------------------------------------------------
    // Handled implicitly in the PC next‑fetch logic above.

    // ------------------------------------------------------------
    //  Timer Counter (generates timer_int)
    // ------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timer_cnt     <= 8'd0;
            timer_int_int <= 1'b0;
        end else if (clk_en) begin
            if (timer_cnt == 8'd10) begin
                timer_cnt     <= 8'd0;
                timer_int_int <= 1'b1;
            end else begin
                timer_cnt     <= timer_cnt + 1'b1;
                timer_int_int <= 1'b0;
            end
        end
    end
    assign timer_int = timer_int_int;

    // ------------------------------------------------------------
    //  Output Assignments
    // ------------------------------------------------------------
    assign data_out = data_mem[addr];
    assign we       = (state == S_WRITEBACK) && (pipe_reg.opcode == OP_SW);
    // timer_int is already driven by timer_int_int

    // Memory write enable (we) is also used to write data_mem
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // No write on reset
        end else if (we && clk_en) begin
            data_mem[addr] <= data_in;
        end
    end

    // ------------------------------------------------------------
    //  Initialize Instruction Memory (for simulation only)
    // ------------------------------------------------------------
    initial begin
        for (int i = 0; i < INSTR_MEM_SIZE; i = i + 1) begin
            instr_mem[i] = 32'h0000_0060; // NOP-like encoding (opcode=OP_NOP)
        end
    end

endmodule

module traffic_light_controller (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         emergency_req,
    input  logic         pedestrian_req,
    input  logic         sensor_ns_car,
    input  logic         sensor_ew_car,
    output logic         ns_red_o,
    output logic         ns_yellow_o,
    output logic         ns_green_o,
    output logic         ew_red_o,
    output logic         ew_yellow_o,
    output logic         ew_green_o,
    output logic         pedestrian_walk_o,
    output logic         pedestrian_dont_walk_o,
    output logic [2:0]   current_state_debug_o
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE            = 3'b000,
        NS_GREEN        = 3'b001,
        NS_YELLOW       = 3'b010,
        ALL_RED_1       = 3'b011,
        EW_GREEN        = 3'b100,
        EW_YELLOW       = 3'b101,
        ALL_RED_2       = 3'b110,
        PEDESTRIAN_MODE = 3'b111
    } state_t;

    // Internal registers
    state_t current_state, next_state;

    logic [15:0] timer_counter;
    logic [15:0] ns_green_timer;
    logic [15:0] ew_green_timer;
    logic [7:0]  yellow_timer;
    logic [7:0]  all_red_timer;
    logic [7:0]  pedestrian_timer;

    logic        emergency_active;
    logic        pedestrian_requested;
    logic        ns_priority_flag;
    logic        ew_priority_flag;

    logic [15:0] default_ns_duration;
    logic [15:0] default_ew_duration;
    logic [7:0]  min_green_duration;

    // Timer expiration signal
    logic timer_expired;

    // Assign debug output
    assign current_state_debug_o = current_state;

    // Timer expiration detection
    assign timer_expired = (timer_counter == 16'd0);

    // Sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            timer_counter <= 16'd0;
            ns_green_timer <= 16'd50000; // Default 1ms at 50MHz
            ew_green_timer <= 16'd50000;
            yellow_timer <= 8'd50;       // 1us at 50MHz
            all_red_timer <= 8'd25;      // 0.5us at 50MHz
            pedestrian_timer <= 8'd100;  // 2us at 50MHz
            emergency_active <= 1'b0;
            pedestrian_requested <= 1'b0;
            ns_priority_flag <= 1'b0;
            ew_priority_flag <= 1'b0;
            default_ns_duration <= 16'd50000;
            default_ew_duration <= 16'd50000;
            min_green_duration <= 8'd25;
        end else begin
            current_state <= next_state;

            // Update timer
            if (timer_expired)
                timer_counter <= 16'd0;
            else
                timer_counter <= timer_counter - 1'b1;

            // Update flags
            emergency_active <= emergency_req;
            if (pedestrian_req)
                pedestrian_requested <= 1'b1;
            if (current_state == PEDESTRIAN_MODE)
                pedestrian_requested <= 1'b0;

            ns_priority_flag <= sensor_ns_car;
            ew_priority_flag <= sensor_ew_car;
        end
    end

    // Next state logic
    always_comb begin
        case (current_state)
            IDLE:          next_state = NS_GREEN;
            NS_GREEN:      
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else if (timer_expired && (!ns_priority_flag || ew_priority_flag || pedestrian_requested))
                    next_state = NS_YELLOW;
                else
                    next_state = NS_GREEN;
            NS_YELLOW:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = ALL_RED_1;
            ALL_RED_1:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = EW_GREEN;
            EW_GREEN:      
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else if (timer_expired && (!ew_priority_flag || ns_priority_flag || pedestrian_requested))
                    next_state = EW_YELLOW;
                else
                    next_state = EW_GREEN;
            EW_YELLOW:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = ALL_RED_2;
            ALL_RED_2:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else if (pedestrian_requested)
                    next_state = PEDESTRIAN_MODE;
                else
                    next_state = NS_GREEN;
            PEDESTRIAN_MODE: 
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = ALL_RED_2;
            default:       
                next_state = IDLE;
        endcase
    end

    // Output logic
    always_comb begin
        // Default assignments
        ns_red_o = 1'b0;
        ns_yellow_o = 1'b0;
        ns_green_o = 1'b0;
        ew_red_o = 1'b0;
        ew_yellow_o = 1'b0;
        ew_green_o = 1'b0;
        pedestrian_walk_o = 1'b0;
        pedestrian_dont_walk_o = 1'b0;

        case (current_state)
            IDLE: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            NS_GREEN: begin
                ns_green_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            NS_YELLOW: begin
                ns_yellow_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            ALL_RED_1: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            EW_GREEN: begin
                ns_red_o = 1'b1;
                ew_green_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            EW_YELLOW: begin
                ns_red_o = 1'b1;
                ew_yellow_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            ALL_RED_2: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            PEDESTRIAN_MODE: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_walk_o = 1'b1;
            end
            default: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
        endcase
    end

    // Timer loading logic
    always_comb begin
        case (next_state)
            NS_GREEN:      timer_counter = ns_green_timer;
            EW_GREEN:      timer_counter = ew_green_timer;
            NS_YELLOW,
            EW_YELLOW:     timer_counter = yellow_timer;
            ALL_RED_1,
            ALL_RED_2:     timer_counter = all_red_timer;
            PEDESTRIAN_MODE: timer_counter = pedestrian_timer;
            default:       timer_counter = 16'd0;
        endcase
    end

endmodule

