    output logic         ns_red_o,
    output logic         ns_yellow_o,
    output logic         ns_green_o,
    output logic         ew_red_o,
    output logic         ew_yellow_o,
    output logic         ew_green_o,
    output logic         pedestrian_walk_o,
    output logic         pedestrian_dont_walk_o,
    output logic [2:0]   current_state_debug_o
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE            = 3'b000,
        NS_GREEN        = 3'b001,
        NS_YELLOW       = 3'b010,
        ALL_RED_1       = 3'b011,
        EW_GREEN        = 3'b100,
        EW_YELLOW       = 3'b101,
        ALL_RED_2       = 3'b110,
        PEDESTRIAN_MODE = 3'b111
    } state_t;

    // Internal registers
    state_t current_state, next_state;

    logic [15:0] timer_counter;
    logic [15:0] ns_green_timer;
    logic [15:0] ew_green_timer;
    logic [7:0]  yellow_timer;
    logic [7:0]  all_red_timer;
    logic [7:0]  pedestrian_timer;

    logic        emergency_active;
    logic        pedestrian_requested;
    logic        ns_priority_flag;
    logic        ew_priority_flag;

    logic [15:0] default_ns_duration;
    logic [15:0] default_ew_duration;
    logic [7:0]  min_green_duration;

    // Timer expiration signal
    logic timer_expired;

    // Assign debug output
    assign current_state_debug_o = current_state;

    // Timer expiration detection
    assign timer_expired = (timer_counter == 16'd0);

    // Sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            timer_counter <= 16'd0;
            ns_green_timer <= 16'd50000; // Default 1ms at 50MHz
            ew_green_timer <= 16'd50000;
            yellow_timer <= 8'd50;       // 1us at 50MHz
            all_red_timer <= 8'd25;      // 0.5us at 50MHz
            pedestrian_timer <= 8'd100;  // 2us at 50MHz
            emergency_active <= 1'b0;
            pedestrian_requested <= 1'b0;
            ns_priority_flag <= 1'b0;
            ew_priority_flag <= 1'b0;
            default_ns_duration <= 16'd50000;
            default_ew_duration <= 16'd50000;
            min_green_duration <= 8'd25;
        end else begin
            current_state <= next_state;

            // Update timer
            if (timer_expired)
                timer_counter <= 16'd0;
            else
                timer_counter <= timer_counter - 1'b1;

            // Update flags
            emergency_active <= emergency_req;
            if (pedestrian_req)
                pedestrian_requested <= 1'b1;
            if (current_state == PEDESTRIAN_MODE)
                pedestrian_requested <= 1'b0;

            ns_priority_flag <= sensor_ns_car;
            ew_priority_flag <= sensor_ew_car;
        end
    end

    // Next state logic
    always_comb begin
        case (current_state)
            IDLE:          next_state = NS_GREEN;
            NS_GREEN:      
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else if (timer_expired && (!ns_priority_flag || ew_priority_flag || pedestrian_requested))
                    next_state = NS_YELLOW;
                else
                    next_state = NS_GREEN;
            NS_YELLOW:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = ALL_RED_1;
            ALL_RED_1:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = EW_GREEN;
            EW_GREEN:      
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else if (timer_expired && (!ew_priority_flag || ns_priority_flag || pedestrian_requested))
                    next_state = EW_YELLOW;
                else
                    next_state = EW_GREEN;
            EW_YELLOW:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = ALL_RED_2;
            ALL_RED_2:     
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else if (pedestrian_requested)
                    next_state = PEDESTRIAN_MODE;
                else
                    next_state = NS_GREEN;
            PEDESTRIAN_MODE: 
                if (emergency_req && !emergency_active)
                    next_state = ALL_RED_1;
                else
                    next_state = ALL_RED_2;
            default:       
                next_state = IDLE;
        endcase
    end

    // Output logic
    always_comb begin
        // Default assignments
        ns_red_o = 1'b0;
        ns_yellow_o = 1'b0;
        ns_green_o = 1'b0;
        ew_red_o = 1'b0;
        ew_yellow_o = 1'b0;
        ew_green_o = 1'b0;
        pedestrian_walk_o = 1'b0;
        pedestrian_dont_walk_o = 1'b0;

        case (current_state)
            IDLE: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            NS_GREEN: begin
                ns_green_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            NS_YELLOW: begin
                ns_yellow_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            ALL_RED_1: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            EW_GREEN: begin
                ns_red_o = 1'b1;
                ew_green_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            EW_YELLOW: begin
                ns_red_o = 1'b1;
                ew_yellow_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            ALL_RED_2: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
            PEDESTRIAN_MODE: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_walk_o = 1'b1;
            end
            default: begin
                ns_red_o = 1'b1;
                ew_red_o = 1'b1;
                pedestrian_dont_walk_o = 1'b1;
            end
        endcase
    end

    // Timer loading logic
    always_comb begin
        case (next_state)
            NS_GREEN:      timer_counter = ns_green_timer;
            EW_GREEN:      timer_counter = ew_green_timer;
            NS_YELLOW,
            EW_YELLOW:     timer_counter = yellow_timer;
            ALL_RED_1,
            ALL_RED_2:     timer_counter = all_red_timer;
            PEDESTRIAN_MODE: timer_counter = pedestrian_timer;
            default:       timer_counter = 16'd0;
        endcase
    end

endmodule
