module traffic_light_fsm (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        sensor_detect,
    input  logic        emergency_req,
    output logic        red_o,
    output logic        yellow_o,
    output logic        green_o,
    output logic [1:0]  state_debug
);

    // State encoding
    typedef enum logic [1:0] {
        RED_STATE       = 2'b00,
        GREEN_STATE     = 2'b01,
        YELLOW_STATE    = 2'b10,
        EMERGENCY_STATE = 2'b11
    } traffic_state_e;

    // Internal registers
    traffic_state_e current_state, next_state;
    logic [3:0] timer_counter;
    logic [3:0] timer_reload;
    logic       emergency_latch;

    // Timer values
    localparam RED_TIME     = 4'd10;
    localparam GREEN_TIME   = 4'd8;
    localparam GREEN_SHORT  = 4'd3;
    localparam YELLOW_TIME  = 4'd4;

    // Sequential block for state and timer
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state   <= RED_STATE;
            timer_counter   <= RED_TIME;
            emergency_latch <= 1'b0;
        end else begin
            current_state   <= next_state;
            timer_counter   <= (next_state != current_state) ? timer_reload : 
                               (timer_counter > 0) ? timer_counter - 1 : 0;
            emergency_latch <= emergency_req | (emergency_latch & ~red_o);
        end
    end

    // Combinational block for next state logic
    always_comb begin
        // Default assignments
        next_state   = current_state;
        timer_reload = timer_counter;

        case (current_state)
            RED_STATE: begin
                if (emergency_latch)
                    next_state = EMERGENCY_STATE;
                else if (timer_counter == 0)
                    next_state = GREEN_STATE;
            end

            GREEN_STATE: begin
                if (emergency_latch)
                    next_state = EMERGENCY_STATE;
                else if (timer_counter == 0 || (sensor_detect && timer_counter <= 5))
                    next_state = YELLOW_STATE;
            end

            YELLOW_STATE: begin
                if (emergency_latch)
                    next_state = EMERGENCY_STATE;
                else if (timer_counter == 0)
                    next_state = RED_STATE;
            end

            EMERGENCY_STATE: begin
                if (!emergency_latch)
                    next_state = RED_STATE;
            end

            default: next_state = RED_STATE;
        endcase

        // Set reload values based on next state
        unique case (next_state)
            RED_STATE:       timer_reload = RED_TIME;
            GREEN_STATE:     timer_reload = sensor_detect ? GREEN_SHORT : GREEN_TIME;
            YELLOW_STATE:    timer_reload = YELLOW_TIME;
            EMERGENCY_STATE: timer_reload = 4'hF; // Don't care in emergency
            default:         timer_reload = RED_TIME;
        endcase
    end

    // Output logic
    always_comb begin
        red_o    = 1'b0;
        yellow_o = 1'b0;
        green_o  = 1'b0;

        case (current_state)
            RED_STATE:       red_o    = 1'b1;
            GREEN_STATE:     green_o  = 1'b1;
            YELLOW_STATE:    yellow_o = 1'b1;
            EMERGENCY_STATE: red_o    = 1'b1;
            default:         red_o    = 1'b1;
        endcase
    end

    // Debug output
    assign state_debug = current_state;

endmodule

