module universal_counter (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       enable,
    input  logic       load,
    input  logic       up_down,
    input  logic [7:0] data_in,
    output logic [7:0] count_out
);

    // Internal storage for the counter value
    logic [7:0] count_reg;
    logic [7:0] next_count;

    // Arithmetic results
    logic [7:0] increment_result;
    logic [7:0] decrement_result;

    // Assign arithmetic operations
    assign increment_result = count_reg + 1'b1;
    assign decrement_result = count_reg - 1'b1;

    // Combinational logic to determine next count value
    always_comb begin
        unique case ({load, enable})
            2'b10, 2'b11: next_count = data_in;  // Load has priority
            2'b01:        next_count = up_down ? increment_result : decrement_result;
            default:      next_count = count_reg;  // Hold current value
        endcase
    end

    // Sequential block for counter register
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= 8'h00;
        end else begin
            count_reg <= next_count;
        end
    end

    // Output assignment
    assign count_out = count_reg;

endmodule

