class Transaction;
    rand logic       enable;
    rand logic       load;
    rand logic       up_down;
    rand logic [7:0] data_in;
    rand logic [7:0] count_out;

    constraint c_data_in { data_in >= 0; data_in < 256; }
    constraint c_count_out { count_out >= 0; count_out < 256; }

    function void do_copy(Transaction rhs);
        if(rhs == null) return;
        this.enable   = rhs.enable;
        this.load     = rhs.load;
        this.up_down  = rhs.up_down;
        this.data_in  = rhs.data_in;
        this.count_out= rhs.count_out;
    endfunction
endclass

