// universal_fifo_v1.sv
// Module: universal_fifo_v1
// Description: A synchronous FIFO with a depth of 16 and a width of 8 bits.

module universal_fifo_v1 (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       wr_en,
    input  logic [7:0] wr_data,
    input  logic       rd_en,
    output logic [7:0] rd_data,
    output logic       full,
    output logic       empty
);

// Internal Registers
logic [3:0] wr_ptr;
logic [3:0] rd_ptr;
logic [4:0] count;
logic [7:0] fifo_ram [15:0];

// FSM States
typedef enum logic [1:0] {IDLE, WRITE, READ} state_t;
state_t state;
state_t next_state;

// Combinational Logic
always_comb begin
    next_state = state;
    case (state)
        IDLE: begin
            if (wr_en) begin
                next_state = WRITE;
            end else if (rd_en) begin
                next_state = READ;
            end
        end
        WRITE: begin
            next_state = IDLE;
        end
        READ: begin
            next_state = IDLE;
        end
    endcase
end

// Sequential Logic
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        wr_ptr <= 4'd0;
        rd_ptr <= 4'd0;
        count <= 5'd0;
        fifo_ram <= '{default: 8'd0};
    end else begin
        state <= next_state;
        case (state)
            IDLE: begin
                // Do nothing
            end
            WRITE: begin
                fifo_ram[wr_ptr] <= wr_data;
                wr_ptr <= wr_ptr + 1;
                count <= count + 1;
            end
            READ: begin
                rd_data <= fifo_ram[rd_ptr];
                rd_ptr <= rd_ptr + 1;
                count <= count - 1;
            end
        endcase
    end
end

// Combinational Logic for full and empty flags
always_comb begin
    full = (count == 5'd16);
    empty = (count == 5'd0);
end

endmodule

