        if (rd_data !== 8'hAA) begin
            $display("Error: Read data is incorrect");
            $finish;
        end

        // Check if FIFO is empty
        @(posedge clk);
        if (empty !== 1) begin
            $display("Error: FIFO should be empty after read");
            $finish;
        end

