        for (int i = 0; i < 16; i++) begin
            wr_en = 1;
            wr_data = i;
            @(posedge clk);
            wr_en = 0;
        end

        // Check if FIFO is full
        @(posedge clk);
        if (full !== 1) begin
            $display("Error: FIFO should be full after 16 writes");
            $finish;
        end

        // Read 16 bytes of data from FIFO
        for (int i = 0; i < 16; i++) begin
            rd_en = 1;
