            rd_en = 0;
            @(posedge clk);
            if (rd_data !== i) begin
                $display("Error: Read data is incorrect");
                $finish;
            end
        end

        // Check if FIFO is empty
        @(posedge clk);
        if (empty !== 1) begin
            $display("Error: FIFO should be empty after 16 reads");
            $finish;
        end

        $display("Test passed");
        $finish;
    end

    always #5 clk = ~clk;
